(window.PARENT_DIGEST = window.PARENT_DIGEST || {})[6] = {"grade":6,"subjects":[{"id":"toan","name":"Toán","b":[{"t":"Toán 6, tập 1","c":[{"t":"Chương I. Tập hợp các số tự nhiên","l":[{"t":"Bài 1. Tập hợp","req":["Nhận biết tập hợp và các phần tử của nó; sử dụng kí hiệu ∈, ∉.","Mô tả tập hợp bằng cách liệt kê phần tử hoặc chỉ ra tính chất đặc trưng."],"sum":["Tập hợp là một khái niệm cơ bản; người ta thường đặt tên tập hợp bằng chữ cái in hoa A, B, C,… Các phần tử của tập hợp được viết trong dấu { }, cách nhau bởi dấu \";\".","Khái niệm: Tập hợp là một khái niệm cơ bản; người ta thường đặt tên tập hợp bằng chữ cái in hoa A, B, C,… Các phần tử của tập hợp được viết trong dấu { }, cách…","Có hai cách mô tả một tập hợp: Liệt kê các phần tử, ví dụ A = {0;","Tập hợp các số tự nhiên kí hiệu là ℕ = {0: 1;"],"e":["Hay nhầm: 5 không có trong danh sách phần tử của A.","Hay nhầm: Phải dùng dấu ngoặc nhọn { }.","Hay nhầm: Mỗi phần tử chỉ liệt kê một lần.","Hay nhầm: Phải dùng dấu ngoặc nhọn { }."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 2. Cách ghi số tự nhiên","req":["Đọc, viết số tự nhiên trong hệ thập phân; phân biệt số và chữ số, giá trị của chữ số theo vị trí.","Đọc và viết các số La Mã không quá 30."],"sum":["Hệ thập phân dùng mười chữ số 0; 1;","Hệ thập phân dùng mười chữ số 0: 1;","Khi viết số có nhiều chữ số…: Khi viết số có nhiều chữ số, ta tách thành từng lớp ba chữ số từ phải sang trái: lớp đơn vị, lớp nghìn, lớp triệu, lớp tỉ.","Số La Mã dùng các chữ I (1), V (5), X (10): Các số đặc biệt IV = 4, IX = 9."],"e":["Hay nhầm: Chữ số 5 ở hàng trăm nên có giá trị 500.","Hay nhầm: Không viết bốn chữ I liền nhau."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 3. Thứ tự trong tập hợp các số tự nhiên","req":["Biểu diễn số tự nhiên trên tia số; so sánh hai số tự nhiên.","Nhận biết số liền trước, liền sau; sử dụng kí hiệu ≤, ≥."],"sum":["Mỗi số tự nhiên được biểu diễn bởi một điểm trên tia số. Trên tia số nằm ngang, điểm biểu diễn số nhỏ hơn nằm bên trái điểm biểu diễn số lớn hơn.","Mỗi số tự nhiên được biểu diễn bởi một điểm trên tia số: Trên tia số nằm ngang, điểm biểu diễn số nhỏ hơn nằm bên trái điểm biểu diễn số lớn hơn.","Trong hai số tự nhiên khác nhau, có một số nhỏ hơn số kia: Nếu a < b và b < c thì a < c (tính chất bắc cầu).","Mỗi số tự nhiên có đúng một…: Mỗi số tự nhiên có đúng một số liền sau; mỗi số tự nhiên khác 0 có đúng một số liền trước.","A ≤ b nghĩa là a <…: A ≤ b nghĩa là a < b hoặc a = b; a ≥ b nghĩa là a > b hoặc a = b."],"e":["Hay nhầm: Liền sau chỉ hơn 1 đơn vị.","Hay nhầm: 0 nhỏ hơn 1 và là số tự nhiên.","Hay nhầm: Số 0 là số tự nhiên nhỏ nhất.","Hay nhầm: Tính chất bắc cầu cho a < 15.","Hay nhầm: a nhỏ hơn b nên nhỏ hơn 15."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 4. Phép cộng và phép trừ số tự nhiên","req":["Thực hiện phép cộng, phép trừ số tự nhiên; vận dụng tính chất giao hoán, kết hợp để tính nhẩm, tính hợp lí."],"sum":["Phép cộng: a + b = c (a, b là số hạng, c là tổng). Phép cộng có tính chất giao hoán a + b = b + a và kết hợp (a + b) + c = a + (b + c); a + 0 = a.","Phép cộng: A + b = c (a, b là số hạng, c là tổng).","Phép trừ: A − b = c (a là số bị trừ, b là số trừ, c là hiệu), chỉ thực hiện được trong ℕ khi a ≥ b.","Mẹo tính nhanh: Nhóm các số hạng có tổng tròn chục, tròn trăm; thêm vào số hạng này và bớt đi ở số hạng kia cùng một số."],"e":["Hay nhầm: Kết hợp là (a + b) + c = a + (b + c).","Hay nhầm: Liên quan phép nhân và phép cộng.","Hay nhầm: Hiệu sẽ không là số tự nhiên."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 5. Phép nhân và phép chia số tự nhiên","req":["Thực hiện phép nhân, phép chia (hết và có dư) số tự nhiên; vận dụng tính chất của phép nhân để tính nhẩm, tính hợp lí."],"m":[{"t":"Tìm số chưa biết x trong phép tính","w":"Đề cho \"tìm x biết...\" với số tự nhiên, x là một thành phần của phép cộng, trừ, nhân, chia.","s":["Xác định x đóng vai trò gì: số hạng, số bị trừ, số trừ, thừa số, số bị chia hay số chia.","Dùng quy tắc ngược: số hạng = tổng − số hạng kia; số bị trừ = hiệu + số trừ; số trừ = số bị trừ − hiệu; thừa số = tích : thừa số kia; số bị chia = thương × số chia; số…","Nếu x nằm trong biểu thức, coi cả biểu thức đó là một thành phần, tìm nó trước rồi mới tìm x.","Thử lại bằng cách thay x vào đề."],"n":["Tính biểu thức không chứa x ở vế phải trước.","Một ngoặc chứa x được xem là một thành phần: ví dụ 125 : (x + 2) = 25 thì x + 2 là số chia.","Không đổi chỗ số bị trừ và số trừ; không đổi chỗ số bị chia và số chia."]}],"sum":["Phép nhân: a × b = c (a, b là thừa số, c là tích). Tính chất: giao hoán a·b = b·a; kết hợp (a·b)·c = a·(b·c); nhân với 1: a·1 = a; phân phối đối với phép cộng và phép trừ.","Phép nhân: A × b = c (a, b là thừa số, c là tích).","Phép chia hết: A = b·q (b ≠ 0), q là thương."],"d":["Tìm số chưa biết x trong phép tính"],"e":["Hay nhầm: Số dư luôn nhỏ hơn số chia.","Hay nhầm: Khi đó còn chia tiếp được.","Hay nhầm: Khi r = 0 là phép chia hết.","Hay nhầm: Kết hợp là (a·b)·c = a·(b·c).","Lưu ý: Tính biểu thức không chứa x ở vế phải trước.","Lưu ý: Một ngoặc chứa x được xem là một thành phần: ví dụ 125 : (x + 2) = 25 thì x + 2 là số chia."],"q":{"n":14,"lv":{"Biết":3,"Hiểu":7,"Vận dụng":4}}},{"t":"Bài 6. Luỹ thừa với số mũ tự nhiên","req":["Thực hiện phép tính luỹ thừa với số mũ tự nhiên; nhân, chia hai luỹ thừa cùng cơ số."],"sum":["Luỹ thừa bậc n của a là tích của n thừa số bằng nhau, mỗi thừa số bằng a (n ∈ ℕ*). a là cơ số, n là số mũ. a² đọc là a bình phương, a³ đọc là a lập phương.","Khái niệm: Luỹ thừa bậc n của a là tích của n thừa số bằng nhau, mỗi thừa số bằng a (n ∈ ℕ*). a là cơ số, n là số mũ. a² đọc là a bình phương, a³ đọc là a lập…","Mọi số tự nhiên đều viết được…: Mọi số tự nhiên đều viết được dưới dạng tổng giá trị các chữ số nhân với luỹ thừa của 10, ví dụ 2 345 = 2·10³ + 3·10² + 4·10 + 5."],"e":["Hay nhầm: Đó là phép nhân, không phải luỹ thừa."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 7. Thứ tự thực hiện các phép tính","req":["Nắm thứ tự thực hiện phép tính trong biểu thức có và không có dấu ngoặc; tính giá trị biểu thức."],"m":[{"t":"Tính giá trị biểu thức có nhiều phép tính","w":"Đề cho biểu thức có cộng, trừ, nhân, chia, lũy thừa và dấu ngoặc, yêu cầu \"tính giá trị\" hoặc \"thực hiện phép tính\".","s":["Quan sát biểu thức: có ngoặc không, có lũy thừa không, có nhân chia không.","Xác định thứ tự: không có ngoặc thì lũy thừa → nhân, chia → cộng, trừ; có ngoặc thì ( ) trước, rồi [ ], rồi { }.","Làm từng bước nhỏ, mỗi bước chỉ tính một nhóm phép tính và viết lại biểu thức sau bước đó; các phép tính cùng cấp làm từ trái sang phải.","Kiểm tra lại bằng cách ước lượng hoặc tính lại bước dễ sai (dấu trừ, lũy thừa)."],"n":["Cộng trừ cùng cấp thì làm từ trái sang phải; nhân chia cũng vậy. Ví dụ 12 − 5 + 3 = 10 chứ không phải 4.","Lũy thừa có số mũ chỉ áp dụng cho số đứng ngay trước nó: 2·3² = 2·9, không phải 6².","Với nhiều lớp ngoặc, làm từ ngoặc trong cùng ra ngoài."]}],"sum":["Biểu thức không có dấu ngoặc: chỉ có cộng, trừ hoặc chỉ có nhân, chia thì làm từ trái sang phải.","Biểu thức không có dấu ngoặc: Chỉ có cộng, trừ hoặc chỉ có nhân, chia thì làm từ trái sang phải.","Biểu thức có dấu ngoặc: Làm trong ngoặc tròn ( ) trước, rồi ngoặc vuông [ ], cuối cùng ngoặc nhọn { }."],"d":["Tính giá trị biểu thức có nhiều phép tính"],"e":["Hay nhầm: Chỉ áp dụng khi cùng loại phép tính.","Lưu ý: Cộng trừ cùng cấp thì làm từ trái sang phải; nhân chia cũng vậy. Ví dụ 12 − 5 + 3 = 10 chứ không phải 4.","Lưu ý: Lũy thừa có số mũ chỉ áp dụng cho số đứng ngay trước nó: 2·3² = 2·9, không phải 6².","Lưu ý: Với nhiều lớp ngoặc, làm từ ngoặc trong cùng ra ngoài."],"q":{"n":13,"lv":{"Biết":2,"Hiểu":7,"Vận dụng":4}}}]},{"t":"Chương II. Tính chia hết trong tập hợp các số tự nhiên","l":[{"t":"Bài 8. Quan hệ chia hết và tính chất","req":["Nhận biết quan hệ chia hết, ước và bội; vận dụng tính chất chia hết của một tổng."],"sum":["Cho a, b ∈ ℕ, b ≠ 0. Nếu có q ∈ ℕ sao cho a = b·q thì a chia hết cho b, kí hiệu a ⋮ b; khi đó a là bội của b, b là ước của a.","Cho a, b ∈ ℕ, b ≠ 0: Nếu có q ∈ ℕ sao cho a = b·q thì a chia hết cho b, kí hiệu a ⋮ b; khi đó a là bội của b, b là ước của a.","Tìm ước của a: Chia a lần lượt cho 1, 2, …, a.","Tính chất 1: Nếu tất cả các số hạng của tổng đều chia hết cho cùng một số thì tổng chia hết cho số đó: a ⋮ m, b ⋮ m ⇒ (a + b) ⋮ m.","Tính chất 2: Nếu chỉ có một số hạng của tổng không chia hết cho một số, các số hạng còn lại đều chia hết cho số đó, thì tổng không chia hết cho số đó."],"e":["Hay nhầm: 13 không chia hết cho 6 nên tổng không chia hết."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 9. Dấu hiệu chia hết","req":["Nhận biết và vận dụng dấu hiệu chia hết cho 2, 5, 3, 9."],"m":[{"t":"Tìm chữ số chưa biết để số chia hết","w":"Đề cho số có chữ số chưa biết (dạng 47a, 25b) và yêu cầu chia hết cho 2, 3, 5, 9.","s":["Liệt kê các điều kiện chia hết cần thỏa mãn.","Chia hết cho 2 hoặc 5: xét chữ số tận cùng. Chia hết cho 3 hoặc 9: xét tổng các chữ số.","Lập tổng các chữ số (có chữ số chưa biết) rồi tìm các chữ số 0–9 làm tổng chia hết cho 3 hoặc 9.","Kết hợp mọi điều kiện, loại giá trị không thỏa, rồi thử lại."],"n":["Chữ số cần tìm chỉ nhận giá trị 0, 1, ..., 9; chữ số đầu tiên của số phải khác 0.","Chia hết cho 9 thì chia hết cho 3, nhưng chia hết cho 3 chưa chắc chia hết cho 9.","Chia hết cho cả 2 và 5 thì tận cùng là 0."]}],"sum":["Dấu hiệu chia hết cho 2: các số có chữ số tận cùng là chữ số chẵn (0; 2;","Dấu hiệu chia hết cho 2: Các số có chữ số tận cùng là chữ số chẵn (0;","Dấu hiệu chia hết cho 9: Các số có tổng các chữ số chia hết cho 9.","Số chia hết cho 9 thì chia…: Số chia hết cho 9 thì chia hết cho 3 (điều ngược lại không đúng)."],"d":["Tìm chữ số chưa biết để số chia hết"],"e":["Hay nhầm: Tổng chữ số 17 không chia hết cho 9.","Hay nhầm: Số tận cùng 5 không chia hết cho 2.","Lưu ý: Chữ số cần tìm chỉ nhận giá trị 0, 1, ..., 9; chữ số đầu tiên của số phải khác 0.","Lưu ý: Chia hết cho 9 thì chia hết cho 3, nhưng chia hết cho 3 chưa chắc chia hết cho 9.","Lưu ý: Chia hết cho cả 2 và 5 thì tận cùng là 0."],"q":{"n":13,"lv":{"Biết":2,"Hiểu":7,"Vận dụng":4}}},{"t":"Bài 10. Số nguyên tố","req":["Nhận biết số nguyên tố, hợp số; phân tích một số ra thừa số nguyên tố."],"sum":["Số nguyên tố là số tự nhiên lớn hơn 1, chỉ có hai ước là 1 và chính nó. Hợp số là số tự nhiên lớn hơn 1, có nhiều hơn hai ước.","Khái niệm: Số nguyên tố là số tự nhiên lớn hơn 1, chỉ có hai ước là 1 và chính nó.","Các số nguyên tố nhỏ hơn 20: 2;","Phân tích một số ra thừa số…: Phân tích một số ra thừa số nguyên tố là viết số đó dưới dạng tích các thừa số nguyên tố (theo sơ đồ cây hoặc sơ đồ cột)."],"e":["Hay nhầm: Số 2 là số nguyên tố chẵn.","Hay nhầm: 4 và 9 không phải số nguyên tố."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 11. Ước chung. Ước chung lớn nhất","req":["Tìm ước chung, ƯCLN của hai hay nhiều số; nhận biết hai số nguyên tố cùng nhau; rút gọn phân số về tối giản."],"m":[{"t":"Tìm ƯCLN và bài toán thực tế dùng ƯCLN","w":"Đề cho hai số (hoặc nhiều số) và hỏi ước chung lớn nhất, hoặc bài \"chia đều\", \"cắt nhỏ\", \"nhiều nhất\", \"lớn nhất\".","s":["Phân tích mỗi số ra thừa số nguyên tố.","Chọn các thừa số nguyên tố chung của tất cả các số.","Với mỗi thừa số chung lấy số mũ nhỏ nhất.","Nhân các thừa số vừa chọn được ƯCLN; với bài toán thực tế, đối chiếu ý nghĩa và trả lời."],"n":["Nếu số này chia hết cho số kia thì ƯCLN là số nhỏ hơn.","Hai số chỉ có ước chung là 1 gọi là nguyên tố cùng nhau (ƯCLN = 1).","Mọi ước chung của các số đều là ước của ƯCLN."]}],"sum":["Ước chung của hai hay nhiều số là ước của tất cả các số đó; ƯC(a, b).","Ước chung của hai hay nhiều số là ước của tất cả các số đó: ƯC(a, b).","Tìm ƯCLN bằng phân tích ra thừa số nguyên tố: Phân tích các số; chọn các thừa số nguyên tố chung; lập tích các thừa số đã chọn, mỗi thừa số lấy với số mũ nhỏ nhất.","Hai số có ƯCLN bằng 1 gọi là hai số nguyên tố cùng nhau: Phân số a/b tối giản khi ƯCLN(a, b) = 1; rút gọn bằng cách chia tử và mẫu cho ƯCLN."],"d":["Tìm ƯCLN và bài toán thực tế dùng ƯCLN"],"e":["Hay nhầm: Hai số không nhất thiết là số nguyên tố, ví dụ 8 và 9.","Lưu ý: Nếu số này chia hết cho số kia thì ƯCLN là số nhỏ hơn.","Lưu ý: Hai số chỉ có ước chung là 1 gọi là nguyên tố cùng nhau (ƯCLN = 1).","Lưu ý: Mọi ước chung của các số đều là ước của ƯCLN."],"q":{"n":13,"lv":{"Biết":2,"Hiểu":7,"Vận dụng":4}}},{"t":"Bài 12. Bội chung. Bội chung nhỏ nhất","req":["Tìm bội chung, BCNN của hai hay nhiều số; vận dụng BCNN để quy đồng mẫu và giải bài toán thực tế."],"m":[{"t":"Tìm BCNN và bài toán thực tế dùng BCNN","w":"Đề cho hai số và hỏi bội chung nhỏ nhất, hoặc bài \"sau bao lâu lại cùng\", \"ít nhất\", \"nhỏ nhất\".","s":["Phân tích mỗi số ra thừa số nguyên tố.","Chọn tất cả các thừa số nguyên tố, chung và riêng.","Với mỗi thừa số lấy số mũ lớn nhất.","Nhân các thừa số vừa chọn được BCNN; với bài toán thực tế, tìm bội của BCNN thỏa điều kiện đề."],"n":["Nếu số này chia hết cho số kia thì BCNN là số lớn hơn.","Với hai số: ƯCLN × BCNN = tích hai số, dùng để kiểm tra nhanh.","Mọi bội chung đều là bội của BCNN; khi đề có điều kiện khoảng (ví dụ lớn hơn 100) thì liệt kê các bội của BCNN."]}],"sum":["Bội chung của hai hay nhiều số là bội của tất cả các số đó; BC(a, b).","Bội chung của hai hay nhiều số là bội của tất cả các số đó: BC(a, b).","Tìm BCNN: Phân tích các số ra thừa số nguyên tố; chọn các thừa số nguyên tố chung và riêng; lập tích, mỗi thừa số lấy với số mũ lớn nhất.","Nếu a ⋮ b thì BCNN(a, b) = a: Nếu a và b nguyên tố cùng nhau thì BCNN(a, b) = a·b."],"d":["Tìm BCNN và bài toán thực tế dùng BCNN"],"e":["Hay nhầm: Chỉ đúng khi số này chia hết cho số kia.","Lưu ý: Nếu số này chia hết cho số kia thì BCNN là số lớn hơn.","Lưu ý: Với hai số: ƯCLN × BCNN = tích hai số, dùng để kiểm tra nhanh.","Lưu ý: Mọi bội chung đều là bội của BCNN; khi đề có điều kiện khoảng (ví dụ lớn hơn 100) thì liệt kê các bội của BCNN."],"q":{"n":13,"lv":{"Biết":2,"Hiểu":7,"Vận dụng":4}}}]},{"t":"Chương III. Số nguyên","l":[{"t":"Bài 13. Tập hợp các số nguyên","req":["Nhận biết số nguyên âm, tập hợp số nguyên; biểu diễn trên trục số; so sánh hai số nguyên; số đối."],"sum":["Các số −1; −2; −3; … là số nguyên âm. Tập hợp số nguyên ℤ = {…; −3; −2; −1;","Các số −1; −2; −3; … là số nguyên âm: Tập hợp số nguyên ℤ = {…; −3; −2; −1;","Trên trục số nằm ngang, điểm biểu…: Trên trục số nằm ngang, điểm biểu diễn số nguyên a nằm bên trái điểm biểu diễn số nguyên b thì a < b.","Hai số nguyên trên trục số nằm…: Hai số nguyên trên trục số nằm ở hai phía của điểm 0 và cách đều điểm 0 gọi là hai số đối nhau.","Số nguyên âm dùng để biểu thị…: Số nguyên âm dùng để biểu thị nhiệt độ dưới 0 °C, độ cao dưới mực nước biển, số tiền nợ, năm trước Công nguyên…"],"e":["Hay nhầm: −5 nằm bên trái −2 trên trục số."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 14. Phép cộng và phép trừ số nguyên","req":["Thực hiện cộng, trừ số nguyên; vận dụng tính chất của phép cộng để tính hợp lí."],"m":[{"t":"Cộng, trừ số nguyên","w":"Đề cho các phép tính cộng, trừ với số nguyên âm và dương.","s":["Đưa phép trừ về phép cộng: a − b = a + (−b).","Hai số cùng dấu: cộng hai giá trị tuyệt đối rồi giữ dấu chung.","Hai số khác dấu: lấy giá trị tuyệt đối lớn trừ giá trị tuyệt đối nhỏ, kết quả mang dấu của số có giá trị tuyệt đối lớn hơn.","Kiểm tra bằng trục số hoặc ước lượng dấu của kết quả."],"n":["Trừ đi một số âm bằng cộng số dương: a − (−b) = a + b.","Hai số đối nhau có tổng bằng 0.","Số âm phải đặt trong ngoặc khi đứng sau dấu phép tính: 5 + (−3)."]}],"sum":["Cộng hai số nguyên dương: như cộng hai số tự nhiên. Cộng hai số nguyên âm: cộng hai số đối của chúng rồi thêm dấu \"−\" trước kết quả: (−a) + (−b) = −(a + b).","Cộng hai số nguyên dương: Như cộng hai số tự nhiên.","Cộng hai số nguyên khác dấu: Hai số đối nhau thì tổng bằng 0; không đối nhau thì lấy số lớn trừ số nhỏ (trong hai phần số tự nhiên) và đặt trước kết quả dấu của số có phần số tự…","Phép cộng số nguyên có tính chất…: Phép cộng số nguyên có tính chất giao hoán, kết hợp, cộng với 0, cộng với số đối: a + (−a) = 0."],"d":["Cộng, trừ số nguyên"],"e":["Hay nhầm: Phải cộng với số đối của b.","Lưu ý: Trừ đi một số âm bằng cộng số dương: a − (−b) = a + b.","Lưu ý: Hai số đối nhau có tổng bằng 0.","Lưu ý: Số âm phải đặt trong ngoặc khi đứng sau dấu phép tính: 5 + (−3)."],"q":{"n":13,"lv":{"Biết":3,"Hiểu":7,"Vận dụng":3}}},{"t":"Bài 15. Quy tắc dấu ngoặc","req":["Vận dụng quy tắc bỏ dấu ngoặc để tính hợp lí."],"sum":["Khi bỏ dấu ngoặc có dấu \"+\" đứng trước, giữ nguyên dấu các số hạng trong ngoặc: a + (b − c) = a + b − c.","Khái niệm: Khi bỏ dấu ngoặc có dấu \"+\" đứng trước, giữ nguyên dấu các số hạng trong ngoặc: a + (b − c) = a + b − c.","Khi bỏ dấu ngoặc có dấu \"−\"…: Khi bỏ dấu ngoặc có dấu \"−\" đứng trước, phải đổi dấu tất cả các số hạng trong ngoặc: dấu \"+\" thành \"−\", dấu \"−\" thành \"+\": a − (b − c) = a − b + c.","Trong một tổng đại số, có thể…: Trong một tổng đại số, có thể đổi chỗ các số hạng kèm theo dấu của chúng và nhóm các số hạng tuỳ ý."],"e":["Hay nhầm: Dấu \"+\" đứng trước thì giữ nguyên."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 16. Phép nhân số nguyên","req":["Thực hiện phép nhân số nguyên; vận dụng quy tắc dấu và tính chất phép nhân."],"sum":["Nhân hai số nguyên khác dấu: nhân hai phần số tự nhiên rồi đặt dấu \"−\" trước kết quả. Nhân hai số nguyên cùng dấu: tích là số dương.","Nhân hai số nguyên khác dấu: Nhân hai phần số tự nhiên rồi đặt dấu \"−\" trước kết quả.","Phép nhân số nguyên có tính chất…: Phép nhân số nguyên có tính chất giao hoán, kết hợp, nhân với 1, phân phối đối với phép cộng và phép trừ."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 17. Phép chia hết. Ước và bội của một số nguyên","req":["Thực hiện phép chia hết hai số nguyên; tìm ước và bội của một số nguyên."],"sum":["Cho a, b ∈ ℤ, b ≠ 0. Nếu có q ∈ ℤ sao cho a = b·q thì a chia hết cho b; q là thương.","Cho a, b ∈ ℤ, b ≠ 0: Nếu có q ∈ ℤ sao cho a = b·q thì a chia hết cho b; q là thương.","Nếu a ⋮ b thì a là bội của b, b là ước của a: Nếu a là bội của b thì −a cũng là bội của b; nếu b là ước của a thì −b cũng là ước của a.","Ví dụ: Các ước của 6 là ±1; ±2; ±3; ±6 (tám ước)."],"e":["Hay nhầm: Cùng dấu thì thương dương."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}}]},{"t":"Chương IV. Một số hình phẳng trong thực tiễn","l":[{"t":"Bài 18. Hình tam giác đều. Hình vuông. Hình lục giác đều","req":["Nhận dạng và mô tả tam giác đều, hình vuông, lục giác đều; vẽ tam giác đều, hình vuông bằng thước và compa."],"sum":["Tam giác đều có ba cạnh bằng nhau, ba góc bằng nhau (mỗi góc 60°).","Khái niệm: Tam giác đều có ba cạnh bằng nhau, ba góc bằng nhau (mỗi góc 60°).","Hình vuông có bốn cạnh bằng nhau…: Hình vuông có bốn cạnh bằng nhau, bốn góc vuông, hai đường chéo bằng nhau; hai cạnh đối song song.","Lục giác đều có sáu cạnh bằng…: Lục giác đều có sáu cạnh bằng nhau, sáu góc bằng nhau (mỗi góc 120°), ba đường chéo chính bằng nhau.","Hình ảnh trong thực tế: Tổ ong (lục giác đều), gạch lát nền (hình vuông), biển báo nguy hiểm (tam giác đều)."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 19. Hình chữ nhật. Hình thoi. Hình bình hành. Hình thang cân","req":["Nhận dạng và mô tả các yếu tố cơ bản của hình chữ nhật, hình thoi, hình bình hành, hình thang cân."],"sum":["Hình chữ nhật: bốn góc vuông; các cạnh đối song song và bằng nhau; hai đường chéo bằng nhau.","Hình chữ nhật: Bốn góc vuông; các cạnh đối song song và bằng nhau; hai đường chéo bằng nhau.","Hình thoi: Bốn cạnh bằng nhau; các cạnh đối song song; hai đường chéo vuông góc với nhau; các góc đối bằng nhau.","Hình bình hành: Các cạnh đối song song và bằng nhau; các góc đối bằng nhau; hai đường chéo cắt nhau tại trung điểm mỗi đường.","Hình thang cân: Hai cạnh đáy song song; hai cạnh bên bằng nhau; hai đường chéo bằng nhau; hai góc kề một đáy bằng nhau."],"e":["Hay nhầm: Hai đường chéo bằng nhau nhưng không nhất thiết vuông góc.","Hay nhầm: Không nhất thiết vuông góc.","Hay nhầm: Không nhất thiết vuông góc."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 20. Chu vi và diện tích của một số tứ giác đã học","req":["Tính chu vi, diện tích hình vuông, hình chữ nhật, hình thang, hình bình hành, hình thoi; giải bài toán thực tế."],"m":[{"t":"Tính chu vi, diện tích các tứ giác đặc biệt","w":"Đề cho các kích thước của hình chữ nhật, hình vuông, hình thoi, hình bình hành và hỏi chu vi hoặc diện tích.","s":["Xác định đúng hình và ghi công thức: hình chữ nhật S = a·b, P = 2(a + b); hình vuông S = a², P = 4a; hình thoi S = d₁·d₂/2; hình bình hành S = a·h.","Đổi các độ dài về cùng đơn vị.","Thay số vào công thức, tính từng bước.","Ghi kết quả với đơn vị đúng: độ dài (cm, m), diện tích (cm², m²)."],"n":["Chiều cao của hình bình hành là đoạn vuông góc với đáy, không phải cạnh bên.","Diện tích hình thoi dùng hai đường chéo, không phải hai cạnh.","Biết diện tích và một cạnh của hình chữ nhật thì cạnh còn lại bằng diện tích chia cạnh đó."]}],"sum":["Chu vi hình bình hành, hình thang, hình thoi bằng tổng độ dài các cạnh.","Công thức","Chu vi hình bình hành, hình thang…: Chu vi hình bình hành, hình thang, hình thoi bằng tổng độ dài các cạnh."],"d":["Tính chu vi, diện tích các tứ giác đặc biệt"],"e":["Lưu ý: Chiều cao của hình bình hành là đoạn vuông góc với đáy, không phải cạnh bên.","Lưu ý: Diện tích hình thoi dùng hai đường chéo, không phải hai cạnh.","Lưu ý: Biết diện tích và một cạnh của hình chữ nhật thì cạnh còn lại bằng diện tích chia cạnh đó."],"q":{"n":13,"lv":{"Biết":3,"Hiểu":7,"Vận dụng":3}}}]},{"t":"Chương V. Tính đối xứng của hình phẳng trong tự nhiên","l":[{"t":"Bài 21. Hình có trục đối xứng","req":["Nhận biết trục đối xứng của một hình phẳng; nhận biết hình có trục đối xứng trong tự nhiên, nghệ thuật, kiến trúc."],"sum":["Một hình có trục đối xứng d nếu khi gấp hình theo đường thẳng d thì hai phần của hình chồng khít lên nhau.","Khái niệm: Một hình có trục đối xứng d nếu khi gấp hình theo đường thẳng d thì hai phần của hình chồng khít lên nhau.","Số trục đối xứng: Tam giác đều có 3; hình vuông có 4; hình chữ nhật có 2 (đường nối trung điểm hai cạnh đối); hình thoi có 2 (hai đường chéo); hình thang cân có 1;…","Hình bình hành (không phải hình chữ…: Hình bình hành (không phải hình chữ nhật, hình thoi) không có trục đối xứng."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 22. Hình có tâm đối xứng","req":["Nhận biết tâm đối xứng của một hình phẳng; nhận biết hình có tâm đối xứng trong thực tế."],"sum":["Một hình có tâm đối xứng O nếu khi quay hình nửa vòng (180°) quanh điểm O thì hình thu được chồng khít với hình ban đầu.","Khái niệm: Một hình có tâm đối xứng O nếu khi quay hình nửa vòng (180°) quanh điểm O thì hình thu được chồng khít với hình ban đầu.","Hình chữ nhật, hình thoi, hình vuông…: Hình chữ nhật, hình thoi, hình vuông, hình bình hành có tâm đối xứng là giao điểm hai đường chéo; lục giác đều có tâm đối xứng là giao điểm ba đường…","Tam giác đều, hình thang cân không…: Tam giác đều, hình thang cân không có tâm đối xứng."],"e":["Hay nhầm: Quay một vòng thì hình nào cũng trùng."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}}]}]},{"t":"Toán 6, tập 2","c":[{"t":"Chương VI. Phân số","l":[{"t":"Bài 23. Mở rộng khái niệm phân số. Phân số bằng nhau","req":["Nhận biết phân số với tử và mẫu là số nguyên; hai phân số bằng nhau; áp dụng tính chất cơ bản của phân số, rút gọn phân số."],"sum":["Phân số có dạng a/b với a, b ∈ ℤ, b ≠ 0; a là tử số, b là mẫu số. Phân số a/b là kết quả của phép chia a cho b.","Khái niệm: Phân số có dạng a/b với a, b ∈ ℤ, b ≠ 0; a là tử số, b là mẫu số.","Hai phân số a/b và c/d bằng…: Hai phân số a/b và c/d bằng nhau nếu a·d = b·c.","Tính chất cơ bản: Nhân (hoặc chia) cả tử và mẫu với cùng một số nguyên khác 0 (là ước chung của tử và mẫu khi chia) thì được phân số bằng phân số đã cho.","Rút gọn phân số: Chia cả tử và mẫu cho một ước chung khác 1 và −1."],"e":["Hay nhầm: Nhân cả tử và mẫu với −1 được 3/5."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 24. So sánh phân số. Hỗn số dương","req":["Quy đồng mẫu nhiều phân số; so sánh hai phân số; nhận biết hỗn số dương."],"sum":["Quy đồng mẫu: tìm mẫu chung (thường là BCNN của các mẫu dương), tìm thừa số phụ của mỗi mẫu, nhân tử và mẫu với thừa số phụ tương ứng.","Quy đồng mẫu: Tìm mẫu chung (thường là BCNN của các mẫu dương), tìm thừa số phụ của mỗi mẫu, nhân tử và mẫu với thừa số phụ tương ứng.","So sánh hai phân số cùng mẫu dương: Phân số nào có tử lớn hơn thì lớn hơn.","Phân số lớn hơn 0 gọi là…: Phân số lớn hơn 0 gọi là phân số dương; nhỏ hơn 0 gọi là phân số âm.","Hỗn số dương: Phân số dương lớn hơn 1 có thể viết dưới dạng a b/c (phần nguyên a và phần phân số b/c < 1)."],"e":["Hay nhầm: Cùng mẫu, tử nhỏ hơn thì nhỏ hơn."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 25. Phép cộng và phép trừ phân số","req":["Thực hiện cộng, trừ phân số; vận dụng tính chất để tính hợp lí; số đối của phân số."],"m":[{"t":"Cộng, trừ phân số khác mẫu","w":"Đề cho hai hay nhiều phân số có mẫu khác nhau (hoặc có số nguyên) cần cộng, trừ.","s":["Rút gọn từng phân số về tối giản và đưa mẫu về số dương.","Quy đồng mẫu: tìm BCNN của các mẫu làm mẫu chung, nhân tử và mẫu mỗi phân số với thừa số phụ tương ứng.","Cộng (trừ) các tử, giữ nguyên mẫu chung.","Rút gọn kết quả về phân số tối giản."],"n":["Không cộng hai mẫu với nhau: 1/3 + 1/6 khác 2/9.","Số nguyên viết thành phân số mẫu 1 (3 = 3/1).","Trừ phân số bằng cộng với phân số đối: a/b − c/d = a/b + (−c/d)."]}],"sum":["Cộng hai phân số cùng mẫu: cộng các tử, giữ nguyên mẫu. Khác mẫu: quy đồng mẫu rồi cộng.","Cộng hai phân số cùng mẫu: Cộng các tử, giữ nguyên mẫu.","Phép cộng phân số có tính chất…: Phép cộng phân số có tính chất giao hoán, kết hợp, cộng với 0."],"d":["Cộng, trừ phân số khác mẫu"],"e":["Hay nhầm: Đó là số nghịch đảo của 2/9.","Hay nhầm: Dùng để so sánh hoặc kiểm tra bằng nhau.","Lưu ý: Không cộng hai mẫu với nhau: 1/3 + 1/6 khác 2/9.","Lưu ý: Số nguyên viết thành phân số mẫu 1 (3 = 3/1).","Lưu ý: Trừ phân số bằng cộng với phân số đối: a/b − c/d = a/b + (−c/d)."],"q":{"n":13,"lv":{"Biết":2,"Hiểu":7,"Vận dụng":4}}},{"t":"Bài 26. Phép nhân và phép chia phân số","req":["Thực hiện nhân, chia phân số; vận dụng tính chất của phép nhân phân số; số nghịch đảo."],"sum":["Muốn nhân hai phân số, ta nhân các tử với nhau và nhân các mẫu với nhau.","Khái niệm: Muốn nhân hai phân số, ta nhân các tử với nhau và nhân các mẫu với nhau.","Phép nhân phân số có tính chất…: Phép nhân phân số có tính chất giao hoán, kết hợp, nhân với 1, phân phối đối với phép cộng."],"e":["Hay nhầm: Tích −3/7 · 7/3 = −1, không bằng 1.","Hay nhầm: Phải nhân với số nghịch đảo."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 27. Hai bài toán về phân số","req":["Tìm giá trị phân số của một số cho trước; tìm một số biết giá trị phân số của nó."],"m":[{"t":"Hai bài toán cơ bản về phân số","w":"Bài toán có lời văn: \"tìm m/n của một số\" hoặc \"biết m/n của một số là a, tìm số đó\".","s":["Đọc đề, phân biệt hai trường hợp: biết cả số và tìm một phần (nhân), hoặc biết một phần và tìm cả số (chia).","Trường hợp nhân: giá trị m/n của số b bằng b·m/n.","Trường hợp chia: số biết m/n của nó bằng a là a : m/n = a·n/m.","Tính, kiểm tra lại bằng cách thử ngược, rồi trả lời kèm đơn vị."],"n":["Chữ \"của\" thường báo hiệu phép nhân với phân số.","Phần còn lại cũng là một phân số: còn lại sau khi bán 3/7 là 4/7.","Nhân với phân số rồi thử ngược bằng cách chia để kiểm tra."]}],"sum":["Muốn tìm m/n của số a, ta tính a · m/n.","Khái niệm: Muốn tìm m/n của số a, ta tính a · m/n.","Muốn tìm một số biết m/n của nó bằng b, ta tính b: M/n.","Hai bài toán này thường gặp khi…: Hai bài toán này thường gặp khi tính phần trăm, tính số học sinh, số tiền, quãng đường…"],"d":["Hai bài toán cơ bản về phân số"],"e":["Lưu ý: Chữ \"của\" thường báo hiệu phép nhân với phân số.","Lưu ý: Phần còn lại cũng là một phân số: còn lại sau khi bán 3/7 là 4/7.","Lưu ý: Nhân với phân số rồi thử ngược bằng cách chia để kiểm tra."],"q":{"n":13,"lv":{"Biết":2,"Hiểu":7,"Vận dụng":4}}}]},{"t":"Chương VII. Số thập phân","l":[{"t":"Bài 28. Số thập phân","req":["Nhận biết số thập phân âm, số đối của số thập phân; so sánh hai số thập phân."],"sum":["Phân số thập phân là phân số có mẫu là luỹ thừa của 10. Phân số thập phân có thể viết dưới dạng số thập phân, ví dụ −13/10 = −1,3;","Phân số thập phân là phân số có mẫu là luỹ thừa của 10: Phân số thập phân có thể viết dưới dạng số thập phân, ví dụ −13/10 = −1,3;","Số thập phân gồm phần nguyên (bên…: Số thập phân gồm phần nguyên (bên trái dấu phẩy) và phần thập phân (bên phải dấu phẩy).","So sánh: Số thập phân âm nhỏ hơn 0, nhỏ hơn số thập phân dương."],"e":["Hay nhầm: 3,2 > 3,1 nên −3,2 < −3,1."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 29. Tính toán với số thập phân","req":["Thực hiện cộng, trừ, nhân, chia số thập phân; vận dụng tính chất các phép tính để tính hợp lí."],"sum":["Cộng, trừ, nhân, chia số thập phân âm tương tự như số nguyên: dùng quy tắc dấu, rồi thực hiện với hai số thập phân dương.","Cộng, trừ, nhân, chia số thập phân âm tương tự như số nguyên: Dùng quy tắc dấu, rồi thực hiện với hai số thập phân dương.","Nhân một số thập phân với 10…: Nhân một số thập phân với 10, 100, 1 000… ta dịch dấu phẩy sang phải 1, 2, 3… chữ số; nhân với 0,1;","Thứ tự thực hiện phép tính và…: Thứ tự thực hiện phép tính và các tính chất giao hoán, kết hợp, phân phối áp dụng như với số nguyên."],"e":["Hay nhầm: Cộng hai số âm được số âm."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 30. Làm tròn và ước lượng","req":["Làm tròn số thập phân đến hàng cho trước; ước lượng kết quả phép tính."],"sum":["Quy tắc làm tròn số thập phân dương: nếu chữ số đầu tiên bị bỏ đi nhỏ hơn 5 thì giữ nguyên bộ phận còn lại; nếu lớn hơn hoặc bằng 5 thì cộng thêm 1 vào chữ số cuối cùng của bộ phận còn lại.","Quy tắc làm tròn số thập phân dương: Nếu chữ số đầu tiên bị bỏ đi nhỏ hơn 5 thì giữ nguyên bộ phận còn lại; nếu lớn hơn hoặc bằng 5 thì cộng thêm 1 vào chữ số cuối cùng của bộ phận còn…","Làm tròn số thập phân âm: Làm tròn số đối của nó rồi đặt dấu \"−\" trước kết quả.","Ước lượng kết quả phép tính bằng…: Ước lượng kết quả phép tính bằng cách làm tròn các số rồi tính, giúp kiểm tra nhanh kết quả."],"e":["Hay nhầm: Làm tròn số đối 4,58 ≈ 4,6."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 31. Một số bài toán về tỉ số và tỉ số phần trăm","req":["Tính tỉ số, tỉ số phần trăm của hai số; giải bài toán về tỉ số phần trăm."],"m":[{"t":"Ba bài toán cơ bản về tỉ số phần trăm","w":"Đề hỏi a% của một số, tỉ số phần trăm của hai số, hoặc tìm số khi biết a% của nó.","s":["Xác định đề thuộc loại nào trong ba loại: (1) tìm a% của b; (2) tìm tỉ số phần trăm của a so với b; (3) tìm số biết a% của nó bằng c.","Loại (1): b·a/100. Loại (2): a/b·100%. Loại (3): c·100/a.","Tính, chú ý đưa về cùng đơn vị trước khi so sánh.","Trả lời kèm đơn vị hoặc dấu %; giảm giá x% thì giá mới = giá cũ·(100 − x)/100."],"n":["Tỉ số phần trăm của a so với b là a/b·100%, đừng đảo thứ tự a và b.","Giảm giá 20% nghĩa là còn phải trả 80% giá cũ.","Phần trăm lớn hơn 100% là có thể, khi a lớn hơn b."]}],"sum":["Tỉ số của a và b (b ≠ 0) là thương a : b, kí hiệu a/b. Khi tính tỉ số của hai đại lượng cùng loại phải đưa về cùng đơn vị đo.","Tỉ số của a và b (b ≠ 0) là thương a: B, kí hiệu a/b.","Tìm giá trị phần trăm của một số: M% của a là a·m/100.","Tỉ lệ bản đồ là tỉ số…: Tỉ lệ bản đồ là tỉ số giữa khoảng cách trên bản đồ và khoảng cách thực tế (cùng đơn vị)."],"d":["Ba bài toán cơ bản về tỉ số phần trăm"],"e":["Hay nhầm: Phải đổi về cùng đơn vị: 300 cm và 50 cm.","Lưu ý: Tỉ số phần trăm của a so với b là a/b·100%, đừng đảo thứ tự a và b.","Lưu ý: Giảm giá 20% nghĩa là còn phải trả 80% giá cũ.","Lưu ý: Phần trăm lớn hơn 100% là có thể, khi a lớn hơn b."],"q":{"n":13,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":4}}}]},{"t":"Chương VIII. Những hình hình học cơ bản","l":[{"t":"Bài 32. Điểm và đường thẳng","req":["Nhận biết điểm, đường thẳng, điểm thuộc/không thuộc đường thẳng; ba điểm thẳng hàng; hai đường thẳng cắt nhau, song song."],"sum":["Điểm được kí hiệu bằng chữ cái in hoa (A, B, C…); đường thẳng kí hiệu bằng chữ cái thường (a, b, d…).","Điểm được kí hiệu bằng chữ cái in hoa (A, B, C…): Đường thẳng kí hiệu bằng chữ cái thường (a, b, d…).","Có một và chỉ một đường thẳng…: Có một và chỉ một đường thẳng đi qua hai điểm phân biệt A và B;","Ba điểm cùng thuộc một đường thẳng…: Ba điểm cùng thuộc một đường thẳng gọi là ba điểm thẳng hàng; ngược lại gọi là ba điểm không thẳng hàng.","Hai đường thẳng phân biệt hoặc cắt…: Hai đường thẳng phân biệt hoặc cắt nhau (có một điểm chung – giao điểm) hoặc song song (không có điểm chung)."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 33. Điểm nằm giữa hai điểm. Tia","req":["Nhận biết điểm nằm giữa hai điểm; nhận biết tia, hai tia đối nhau, hai tia trùng nhau."],"sum":["Trong ba điểm thẳng hàng có một và chỉ một điểm nằm giữa hai điểm còn lại. Điểm M nằm giữa A và B thì A, B nằm khác phía đối với M;","Khái niệm: Trong ba điểm thẳng hàng có một và chỉ một điểm nằm giữa hai điểm còn lại.","Điểm O trên đường thẳng xy chia…: Điểm O trên đường thẳng xy chia đường thẳng thành hai phần; mỗi phần cùng với điểm O là một tia gốc O (tia Ox, tia Oy).","Hai tia chung gốc tạo thành một…: Hai tia chung gốc tạo thành một đường thẳng gọi là hai tia đối nhau."],"e":["Hay nhầm: Đó là hai tia trùng nhau."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 34. Đoạn thẳng. Độ dài đoạn thẳng","req":["Nhận biết đoạn thẳng, độ dài đoạn thẳng; so sánh hai đoạn thẳng; khi M nằm giữa A và B thì AM + MB = AB."],"sum":["Đoạn thẳng AB là hình gồm điểm A, điểm B và tất cả các điểm nằm giữa A và B. A, B là hai đầu mút.","Khái niệm: Đoạn thẳng AB là hình gồm điểm A, điểm B và tất cả các điểm nằm giữa A và B.","Mỗi đoạn thẳng có một độ dài, là một số dương: So sánh hai đoạn thẳng bằng cách so sánh độ dài."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 35. Trung điểm của đoạn thẳng","req":["Nhận biết trung điểm của đoạn thẳng; tính độ dài liên quan đến trung điểm."],"m":[{"t":"Tính độ dài đoạn thẳng (điểm nằm giữa, trung điểm)","w":"Đề cho độ dài một vài đoạn thẳng, điểm nằm giữa hoặc trung điểm và hỏi độ dài đoạn còn lại.","s":["Xác định điểm nào nằm giữa hai điểm nào (từ đề hoặc hình vẽ).","Viết đẳng thức cộng đoạn thẳng: M nằm giữa A và B thì AM + MB = AB.","Nếu có trung điểm: M là trung điểm của AB thì AM = MB = AB/2.","Thay số, tính độ dài cần tìm và ghi đơn vị."],"n":["Chỉ được viết AM + MB = AB khi chắc chắn M nằm giữa A và B.","Trung điểm vừa nằm giữa hai đầu mút, vừa cách đều hai đầu mút.","Có nhiều trung điểm lồng nhau thì tính lần lượt từ đoạn lớn đến đoạn nhỏ."]}],"sum":["Trung điểm M của đoạn thẳng AB là điểm nằm giữa A, B và cách đều A, B (MA = MB). Trung điểm còn gọi là điểm chính giữa.","Khái niệm: Trung điểm M của đoạn thẳng AB là điểm nằm giữa A, B và cách đều A, B (MA = MB).","Có thể xác định trung điểm bằng…: Có thể xác định trung điểm bằng thước có vạch chia hoặc gấp giấy, dùng sợi dây…"],"d":["Tính độ dài đoạn thẳng (điểm nằm giữa, trung điểm)"],"e":["Hay nhầm: Cần thêm M nằm giữa A và B.","Lưu ý: Chỉ được viết AM + MB = AB khi chắc chắn M nằm giữa A và B.","Lưu ý: Trung điểm vừa nằm giữa hai đầu mút, vừa cách đều hai đầu mút.","Lưu ý: Có nhiều trung điểm lồng nhau thì tính lần lượt từ đoạn lớn đến đoạn nhỏ."],"q":{"n":13,"lv":{"Biết":3,"Hiểu":7,"Vận dụng":3}}},{"t":"Bài 36. Góc","req":["Nhận biết góc, đỉnh, cạnh của góc; điểm nằm trong góc; góc bẹt."],"sum":["Góc là hình gồm hai tia chung gốc. Gốc chung gọi là đỉnh, hai tia gọi là cạnh của góc.","Góc là hình gồm hai tia chung gốc: Gốc chung gọi là đỉnh, hai tia gọi là cạnh của góc.","Góc bẹt là góc có hai cạnh…: Góc bẹt là góc có hai cạnh là hai tia đối nhau.","Điểm M nằm trong góc xOy (không…: Điểm M nằm trong góc xOy (không phải góc bẹt) nếu M không nằm trên cạnh và nằm giữa hai điểm A ∈ Ox, B ∈ Oy nào đó."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 37. Số đo góc","req":["Đo góc bằng thước đo góc; nhận biết góc nhọn, góc vuông, góc tù, góc bẹt."],"sum":["Mỗi góc có một số đo; số đo góc bẹt là 180°. Số đo của mỗi góc không vượt quá 180°.","Mỗi góc có một số đo; số đo góc bẹt là 180°: Số đo của mỗi góc không vượt quá 180°.","Góc vuông có số đo bằng 90°: Góc nhọn có số đo lớn hơn 0° và nhỏ hơn 90°.","Đo góc: Đặt thước sao cho tâm thước trùng đỉnh góc, một cạnh đi qua vạch 0; cạnh kia đi qua vạch nào thì đó là số đo góc."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}}]},{"t":"Chương IX. Dữ liệu và xác suất thực nghiệm","l":[{"t":"Bài 38. Dữ liệu và thu thập dữ liệu","req":["Nhận biết dữ liệu là số và không phải là số; nhận biết tính hợp lí của dữ liệu; các cách thu thập dữ liệu."],"sum":["Dữ liệu là những thông tin thu thập được như số, chữ, hình ảnh… Dữ liệu là số (số liệu) như chiều cao, điểm số; dữ liệu không phải là số như tên, màu sắc, môn thể thao yêu thích.","Khái niệm: Dữ liệu là những thông tin thu thập được như số, chữ, hình ảnh… Dữ liệu là số (số liệu) như chiều cao, điểm số; dữ liệu không phải là số như tên,…","Dữ liệu cần hợp lí: Phù hợp với tiêu chí đặt ra, không có giá trị vô lí (ví dụ chiều cao học sinh lớp 6 là 3 m).","Cách thu thập dữ liệu: Quan sát, làm thí nghiệm, lập phiếu hỏi (điều tra), phỏng vấn, thu thập từ nguồn có sẵn (sách báo, Internet)."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 39. Bảng thống kê và biểu đồ tranh","req":["Đọc và lập bảng thống kê, biểu đồ tranh; rút ra thông tin từ bảng, biểu đồ."],"sum":["Bảng thống kê gồm các hàng và cột, biểu diễn dữ liệu một cách ngắn gọn, dễ so sánh. Bảng thường có dòng tiêu đề và dòng số liệu tương ứng.","Khái niệm: Bảng thống kê gồm các hàng và cột, biểu diễn dữ liệu một cách ngắn gọn, dễ so sánh.","Biểu đồ tranh dùng biểu tượng hoặc…: Biểu đồ tranh dùng biểu tượng hoặc hình ảnh để biểu diễn dữ liệu.","Khi đọc biểu đồ tranh: Đếm số biểu tượng ở mỗi dòng rồi nhân với giá trị của một biểu tượng."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 40. Biểu đồ cột","req":["Đọc và vẽ biểu đồ cột; phân tích số liệu từ biểu đồ cột."],"sum":["Biểu đồ cột gồm trục ngang ghi các đối tượng, trục đứng ghi số lượng; mỗi đối tượng được biểu diễn bởi một cột, chiều cao cột ứng với số liệu.","Khái niệm: Biểu đồ cột gồm trục ngang ghi các đối tượng, trục đứng ghi số lượng; mỗi đối tượng được biểu diễn bởi một cột, chiều cao cột ứng với số liệu.","Vẽ biểu đồ cột: Vẽ hai trục; chọn khoảng chia thích hợp trên trục đứng; vẽ các cột cách đều, cùng độ rộng; ghi tên biểu đồ, chú thích.","Từ biểu đồ cột có thể so…: Từ biểu đồ cột có thể so sánh, tìm giá trị lớn nhất, nhỏ nhất, tính tổng, tính trung bình."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 41. Biểu đồ cột kép","req":["Đọc và vẽ biểu đồ cột kép; so sánh hai bộ dữ liệu."],"sum":["Biểu đồ cột kép dùng để so sánh hai bộ dữ liệu cùng loại. Mỗi đối tượng trên trục ngang có hai cột đặt sát nhau, phân biệt bằng màu sắc theo chú thích.","Biểu đồ cột kép dùng để so sánh hai bộ dữ liệu cùng loại: Mỗi đối tượng trên trục ngang có hai cột đặt sát nhau, phân biệt bằng màu sắc theo chú thích.","Vẽ biểu đồ cột kép tương tự…: Vẽ biểu đồ cột kép tương tự biểu đồ cột, thêm chú thích màu cho hai bộ dữ liệu.","Đọc biểu đồ cột kép: So sánh hai cột của cùng một đối tượng, hoặc so sánh các cột cùng màu."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 42. Kết quả có thể và sự kiện trong trò chơi, thí nghiệm","req":["Liệt kê các kết quả có thể của trò chơi, thí nghiệm; nhận biết sự kiện chắc chắn, không thể, có thể xảy ra."],"sum":["Khi thực hiện trò chơi hay thí nghiệm, ta có thể liệt kê tất cả các kết quả có thể xảy ra.","Khái niệm: Khi thực hiện trò chơi hay thí nghiệm, ta có thể liệt kê tất cả các kết quả có thể xảy ra.","Sự kiện chắc chắn xảy ra: Luôn xảy ra.","Khi lấy bóng từ hộp, kết quả…: Khi lấy bóng từ hộp, kết quả có thể là màu của quả bóng được lấy ra."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 43. Xác suất thực nghiệm","req":["Tính xác suất thực nghiệm của một sự kiện trong trò chơi, thí nghiệm đơn giản."],"sum":["Xác suất thực nghiệm của sự kiện A khi thực hiện lặp lại trò chơi/thí nghiệm n lần:","Khái niệm: Xác suất thực nghiệm của sự kiện A khi thực hiện lặp lại trò chơi/thí nghiệm n lần:","Xác suất thực nghiệm là một số…: Xác suất thực nghiệm là một số từ 0 đến 1, thường được viết dưới dạng phân số, số thập phân hoặc phần trăm."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}}]}]},{"t":"Bài tập nâng cao","c":[{"t":"Chương I. Tập hợp các số tự nhiên","l":[{"t":"Bài tập nâng cao · Chương I. Tập hợp các số tự nhiên (21 câu)","q":{"n":21,"lv":{"Nâng cao":21}}}]},{"t":"Chương II. Tính chia hết trong tập hợp các số tự nhiên","l":[{"t":"Bài tập nâng cao · Chương II. Tính chia hết trong tập hợp các số tự nhiên (15 câu)","q":{"n":15,"lv":{"Nâng cao":15}}}]},{"t":"Chương III. Số nguyên","l":[{"t":"Bài tập nâng cao · Chương III. Số nguyên (15 câu)","q":{"n":15,"lv":{"Nâng cao":15}}}]},{"t":"Chương IV. Một số hình phẳng trong thực tiễn","l":[{"t":"Bài tập nâng cao · Chương IV. Một số hình phẳng trong thực tiễn (9 câu)","q":{"n":9,"lv":{"Nâng cao":9}}}]},{"t":"Chương V. Tính đối xứng của hình phẳng trong tự nhiên","l":[{"t":"Bài tập nâng cao · Chương V. Tính đối xứng của hình phẳng trong tự nhiên (6 câu)","q":{"n":6,"lv":{"Nâng cao":6}}}]},{"t":"Chương VI. Phân số","l":[{"t":"Bài tập nâng cao · Chương VI. Phân số (15 câu)","q":{"n":15,"lv":{"Nâng cao":15}}}]},{"t":"Chương VII. Số thập phân","l":[{"t":"Bài tập nâng cao · Chương VII. Số thập phân (12 câu)","q":{"n":12,"lv":{"Nâng cao":12}}}]},{"t":"Chương VIII. Những hình hình học cơ bản","l":[{"t":"Bài tập nâng cao · Chương VIII. Những hình hình học cơ bản (18 câu)","q":{"n":18,"lv":{"Nâng cao":18}}}]},{"t":"Chương IX. Dữ liệu và xác suất thực nghiệm","l":[{"t":"Bài tập nâng cao · Chương IX. Dữ liệu và xác suất thực nghiệm (18 câu)","q":{"n":18,"lv":{"Nâng cao":18}}}]}]}]},{"id":"ly","name":"Vật lí","b":[{"t":"Vật lí 6","c":[{"t":"Chương I. Mở đầu về Khoa học tự nhiên","l":[{"t":"Bài 1. Giới thiệu về Khoa học tự nhiên","req":["Nêu được khái niệm Khoa học tự nhiên; vai trò của KHTN trong cuộc sống.","Phân biệt các lĩnh vực chính của KHTN; phân biệt vật sống và vật không sống."],"sum":["Khoa học tự nhiên là một nhánh của khoa học, nghiên cứu các sự vật, hiện tượng, quy luật tự nhiên, những ảnh hưởng của chúng đến cuộc sống con người và môi trường.","Khái niệm: Khoa học tự nhiên là một nhánh của khoa học, nghiên cứu các sự vật, hiện tượng, quy luật tự nhiên, những ảnh hưởng của chúng đến cuộc sống con người…","Hoạt động nghiên cứu khoa học: Tìm hiểu, khám phá ra tri thức khoa học.","Vai trò của KHTN: Nâng cao nhận thức về thế giới tự nhiên;","Các lĩnh vực chủ yếu: Vật lí (vật chất, năng lượng, sự vận động), Hoá học (chất và sự biến đổi của chất), Sinh học (vật sống), Khoa học Trái Đất và Thiên văn học.","Vật sống có các biểu hiện sống: Trao đổi chất, sinh trưởng, sinh sản, cảm ứng… Vật không sống không có các biểu hiện đó."],"e":["Hay nhầm: Chỉ là một phần của Sinh học.","Hay nhầm: Nghiên cứu vật chất, năng lượng, chuyển động.","Hay nhầm: Ứng dụng kĩ thuật xây dựng."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 2. An toàn trong phòng thực hành","req":["Nêu được các quy định an toàn khi học trong phòng thực hành; nhận biết các kí hiệu cảnh báo."],"sum":["Quy định an toàn: chỉ vào phòng thực hành khi có sự đồng ý của giáo viên; mặc trang phục gọn gàng, đeo găng tay, kính bảo vệ mắt khi cần; không ăn uống, đùa nghịch;","Quy định an toàn: Chỉ vào phòng thực hành khi có sự đồng ý của giáo viên; mặc trang phục gọn gàng, đeo găng tay, kính bảo vệ mắt khi cần; không ăn uống, đùa nghịch;","Thực hiện đúng hướng dẫn của giáo…: Thực hiện đúng hướng dẫn của giáo viên; báo ngay khi gặp sự cố (vỡ dụng cụ, đổ hoá chất, cháy…).","Kí hiệu cảnh báo: Hình tam giác viền đen nền vàng là cảnh báo nguy hiểm; hình tròn viền đỏ là cấm; hình vuông viền đỏ nền trắng (hình thoi) là cảnh báo hoá chất (độc,…","Một số kí hiệu: Chất dễ cháy, chất độc, chất ăn mòn, điện cao thế, cấm lửa, lối thoát hiểm."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 5. Đo chiều dài","req":["Nêu được đơn vị đo chiều dài; cách đo chiều dài bằng thước; ước lượng chiều dài."],"m":[{"t":"Đổi đơn vị chiều dài và chọn dụng cụ đo","w":"Đề cho số đo ở đơn vị này, yêu cầu đổi sang đơn vị khác, hoặc hỏi GHĐ, ĐCNN và cách chọn thước.","s":["Xác định đơn vị đang có và đơn vị cần đổi.","Dùng các quan hệ: 1 km = 1 000 m; 1 m = 100 cm = 1 000 mm.","Đổi sang đơn vị nhỏ hơn thì nhân, sang đơn vị lớn hơn thì chia.","Với chọn thước: GHĐ phải lớn hơn hoặc bằng độ dài cần đo, ĐCNN phù hợp độ chính xác yêu cầu."],"n":["Đổi sang đơn vị nhỏ hơn thì số đo tăng, đổi sang đơn vị lớn hơn thì số đo giảm.","Viết kèm đơn vị ở mỗi bước để tránh nhầm.","Kết quả đo ghi theo ĐCNN của thước."]}],"sum":["Đơn vị đo chiều dài trong hệ đơn vị đo lường chính thức của nước ta là mét (m). Các đơn vị thường dùng: kilômét (km), centimét (cm), milimét (mm).","Khái niệm: Đơn vị đo chiều dài trong hệ đơn vị đo lường chính thức của nước ta là mét (m).","Dụng cụ đo: Thước kẻ, thước dây, thước cuộn, thước kẹp… Giới hạn đo (GHĐ) là độ dài lớn nhất ghi trên thước;","Cách đo: Ước lượng chiều dài để chọn thước có GHĐ và ĐCNN phù hợp;"],"d":["Đổi đơn vị chiều dài và chọn dụng cụ đo"],"e":["Lưu ý: Đổi sang đơn vị nhỏ hơn thì số đo tăng, đổi sang đơn vị lớn hơn thì số đo giảm.","Lưu ý: Viết kèm đơn vị ở mỗi bước để tránh nhầm.","Lưu ý: Kết quả đo ghi theo ĐCNN của thước."],"q":{"n":11,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":3}}},{"t":"Bài 6. Đo khối lượng","req":["Nêu được đơn vị đo khối lượng; cách đo khối lượng bằng cân."],"sum":["Mọi vật đều có khối lượng; khối lượng chỉ lượng chất tạo thành vật. Đơn vị đo khối lượng chính thức là kilôgam (kg).","Khái niệm: Mọi vật đều có khối lượng; khối lượng chỉ lượng chất tạo thành vật.","Dụng cụ đo: Cân đồng hồ, cân điện tử, cân đòn, cân Robecvan, cân y tế…","Cách đo: Ước lượng khối lượng để chọn cân phù hợp; hiệu chỉnh cân về số 0;"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 7. Đo thời gian","req":["Nêu được đơn vị đo thời gian; cách đo thời gian bằng đồng hồ."],"sum":["Đơn vị đo thời gian chính thức là giây (s). Các đơn vị khác: phút, giờ, ngày, tuần, tháng, năm.","Đơn vị đo thời gian chính thức là giây (s): Các đơn vị khác: phút, giờ, ngày, tuần, tháng, năm.","Dụng cụ đo: Đồng hồ treo tường, đồng hồ đeo tay, đồng hồ bấm giây, đồng hồ đo thời gian hiện số dùng cổng quang điện.","Cách đo: Ước lượng khoảng thời gian để chọn đồng hồ phù hợp; hiệu chỉnh đồng hồ về số 0; thực hiện đo; mắt nhìn đúng cách;"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 8. Đo nhiệt độ","req":["Nêu được khái niệm nhiệt độ, các thang nhiệt độ; cách đo nhiệt độ bằng nhiệt kế."],"sum":["Nhiệt độ là số đo độ \"nóng\", \"lạnh\" của vật. Không thể dùng cảm giác để xác định chính xác nhiệt độ.","Nhiệt độ là số đo độ \"nóng\", \"lạnh\" của vật: Không thể dùng cảm giác để xác định chính xác nhiệt độ.","Thang nhiệt độ Celsius (°C): Nhiệt độ nước đá đang tan là 0 °C, nước đang sôi là 100 °C.","Nhiệt kế hoạt động dựa trên sự…: Nhiệt kế hoạt động dựa trên sự dãn nở vì nhiệt của chất lỏng (thuỷ ngân, rượu) hoặc cảm biến."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương VIII. Lực trong đời sống","l":[{"t":"Bài 40. Lực là gì?","req":["Lấy được ví dụ về lực đẩy, lực kéo; nêu được lực có thể làm thay đổi tốc độ, hướng chuyển động, biến dạng vật.","Phân biệt lực tiếp xúc và lực không tiếp xúc."],"sum":["Tác dụng đẩy hoặc kéo của vật này lên vật khác gọi là lực. Lực có thể làm vật thay đổi tốc độ, thay đổi hướng chuyển động hoặc biến dạng (hoặc đồng thời).","Tác dụng đẩy hoặc kéo của vật này lên vật khác gọi là lực: Lực có thể làm vật thay đổi tốc độ, thay đổi hướng chuyển động hoặc biến dạng (hoặc đồng thời).","Lực tiếp xúc xuất hiện khi vật…: Lực tiếp xúc xuất hiện khi vật gây ra lực tiếp xúc với vật chịu tác dụng (đá bóng, kéo xe).","Đơn vị của lực là niutơn (N): Dụng cụ đo lực là lực kế (thường dùng lực kế lò xo)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 41. Biểu diễn lực","req":["Biểu diễn được một lực bằng một mũi tên có điểm đặt, phương, chiều, độ lớn."],"m":[{"t":"Biểu diễn lực bằng mũi tên","w":"Đề yêu cầu vẽ hoặc đọc hình biểu diễn lực với tỉ xích cho trước.","s":["Xác định lực: điểm đặt, phương, chiều, độ lớn.","Chọn tỉ xích (ví dụ 1 cm ứng với 10 N).","Tính độ dài mũi tên = độ lớn lực : giá trị một đơn vị tỉ xích.","Vẽ mũi tên: gốc tại điểm đặt, hướng theo chiều lực, dài theo tỉ xích."],"n":["Phương, chiều của trọng lực: thẳng đứng, hướng xuống.","Điểm đặt là gốc mũi tên, đặt trên vật.","Đổi độ lớn lực về cùng đơn vị với tỉ xích."]}],"sum":["Lực có độ lớn, phương và chiều xác định. Lực được biểu diễn bằng một mũi tên: gốc mũi tên là điểm đặt của lực; phương và chiều của mũi tên là phương và chiều của lực;","Lực có độ lớn, phương và chiều xác định: Lực được biểu diễn bằng một mũi tên: gốc mũi tên là điểm đặt của lực; phương và chiều của mũi tên là phương và chiều của lực;","Ví dụ: Lực 30 N, phương ngang, chiều từ trái sang phải, tỉ xích 1 cm ứng với 10 N thì mũi tên dài 3 cm."],"d":["Biểu diễn lực bằng mũi tên"],"e":["Hay nhầm: Trọng lực không nằm ngang.","Hay nhầm: Hướng lên là chiều ngược với trọng lực.","Hay nhầm: Trọng lực không nằm ngang.","Lưu ý: Phương, chiều của trọng lực: thẳng đứng, hướng xuống.","Lưu ý: Điểm đặt là gốc mũi tên, đặt trên vật.","Lưu ý: Đổi độ lớn lực về cùng đơn vị với tỉ xích."],"q":{"n":11,"lv":{"Biết":2,"Hiểu":6,"Vận dụng":3}}},{"t":"Bài 42. Biến dạng của lò xo","req":["Nêu được độ giãn của lò xo treo thẳng đứng tỉ lệ với khối lượng vật treo; tính độ giãn của lò xo."],"m":[{"t":"Bài toán độ dãn của lò xo","w":"Đề cho chiều dài lò xo khi treo các vật khác nhau và hỏi độ dãn, chiều dài khi treo thêm.","s":["Xác định chiều dài tự nhiên l₀ (khi chưa treo vật).","Tính độ dãn Δl = l − l₀.","Trong giới hạn đàn hồi, độ dãn tỉ lệ thuận với trọng lượng vật treo: Δl₁/P₁ = Δl₂/P₂.","Tính đại lượng cần tìm, đổi về cùng đơn vị và kiểm tra giới hạn đàn hồi."],"n":["Độ dãn là hiệu giữa chiều dài lúc có vật và chiều dài tự nhiên, không phải chiều dài lúc có vật.","Treo gấp đôi vật thì độ dãn gấp đôi (trong giới hạn đàn hồi).","Trọng lượng P = 10·m."]}],"sum":["Khi treo vật vào lò xo, lò xo bị dãn ra; khi bỏ vật đi, lò xo trở lại chiều dài ban đầu: đó là biến dạng đàn hồi.","Khái niệm: Khi treo vật vào lò xo, lò xo bị dãn ra; khi bỏ vật đi, lò xo trở lại chiều dài ban đầu: đó là biến dạng đàn hồi.","Độ giãn của lò xo treo thẳng…: Độ giãn của lò xo treo thẳng đứng tỉ lệ với khối lượng của vật treo (khi chưa vượt quá giới hạn đàn hồi)."],"d":["Bài toán độ dãn của lò xo"],"e":["Lưu ý: Độ dãn là hiệu giữa chiều dài lúc có vật và chiều dài tự nhiên, không phải chiều dài lúc có vật.","Lưu ý: Treo gấp đôi vật thì độ dãn gấp đôi (trong giới hạn đàn hồi).","Lưu ý: Trọng lượng P = 10·m."],"q":{"n":11,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":4}}},{"t":"Bài 43. Trọng lượng, lực hấp dẫn","req":["Nêu được khái niệm khối lượng, lực hấp dẫn, trọng lượng; đơn vị và cách tính trọng lượng."],"sum":["Khối lượng là số đo lượng chất của vật. Lực hấp dẫn là lực hút giữa các vật có khối lượng.","Khối lượng là số đo lượng chất của vật: Lực hấp dẫn là lực hút giữa các vật có khối lượng.","Trọng lượng của vật là độ lớn…: Trọng lượng của vật là độ lớn lực hút của Trái Đất tác dụng lên vật.","Trên Mặt Trăng, lực hút nhỏ hơn…: Trên Mặt Trăng, lực hút nhỏ hơn trên Trái Đất khoảng 6 lần nên trọng lượng của vật nhỏ hơn, còn khối lượng không đổi."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 44. Lực ma sát","req":["Nêu được lực ma sát là lực tiếp xúc; các loại ma sát; tác dụng có lợi, có hại của lực ma sát.","Nêu được lực cản của nước."],"sum":["Lực ma sát là lực tiếp xúc xuất hiện ở bề mặt tiếp xúc giữa hai vật. Lực ma sát trượt xuất hiện khi vật trượt trên bề mặt vật khác; lực ma sát nghỉ giữ cho vật không trượt khi bị tác dụng lực.","Khái niệm: Lực ma sát là lực tiếp xúc xuất hiện ở bề mặt tiếp xúc giữa hai vật.","Lực ma sát có thể cản trở…: Lực ma sát có thể cản trở chuyển động (làm mòn lốp, tốn năng lượng) hoặc thúc đẩy chuyển động (giúp ta đi lại, xe chạy, phanh xe).","Tăng ma sát có lợi: Làm lốp xe có khía rãnh, rắc cát lên đường trơn.","Vật chuyển động trong nước chịu lực…: Vật chuyển động trong nước chịu lực cản của nước; diện tích mặt cản càng lớn thì lực cản càng lớn."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương IX. Năng lượng","l":[{"t":"Bài 46. Năng lượng và sự truyền năng lượng","req":["Nêu được năng lượng đặc trưng cho khả năng tác dụng lực; năng lượng có thể truyền từ vật này sang vật khác."],"sum":["Năng lượng đặc trưng cho khả năng tác dụng lực. Vật có năng lượng thì có khả năng tác dụng lực lên vật khác.","Năng lượng đặc trưng cho khả năng tác dụng lực: Vật có năng lượng thì có khả năng tác dụng lực lên vật khác.","Năng lượng có thể truyền từ vật…: Năng lượng có thể truyền từ vật này sang vật khác, từ nơi này sang nơi khác.","Nhiên liệu là những chất khi cháy…: Nhiên liệu là những chất khi cháy giải phóng năng lượng (than, xăng, dầu, khí đốt, củi)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 47. Một số dạng năng lượng","req":["Phân loại được năng lượng theo tiêu chí; nêu được động năng, thế năng hấp dẫn, các dạng năng lượng khác."],"sum":["Năng lượng có thể tồn tại ở nhiều dạng: động năng (vật chuyển động), thế năng hấp dẫn (vật ở trên cao), thế năng đàn hồi (vật bị biến dạng), năng lượng nhiệt, năng lượng ánh sáng, năng lượng âm…","Năng lượng có thể tồn tại ở nhiều dạng: Động năng (vật chuyển động), thế năng hấp dẫn (vật ở trên cao), thế năng đàn hồi (vật bị biến dạng), năng lượng nhiệt, năng lượng ánh sáng, năng…","Động năng của vật càng lớn khi…: Động năng của vật càng lớn khi vật có khối lượng càng lớn và chuyển động càng nhanh.","Năng lượng có thể phân loại thành…: Năng lượng có thể phân loại thành năng lượng tái tạo (Mặt Trời, gió, nước) và năng lượng không tái tạo (than, dầu, khí đốt)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 48. Sự chuyển hoá năng lượng","req":["Nêu được sự chuyển hoá năng lượng; định luật bảo toàn năng lượng."],"sum":["Năng lượng có thể chuyển hoá từ dạng này sang dạng khác. Ví dụ: quạt điện chuyển hoá điện năng thành động năng (cánh quạt), năng lượng âm thanh và nhiệt; pin mặt trời chuyển quang năng thành điện…","Năng lượng có thể chuyển hoá từ dạng này sang dạng khác: Ví dụ: quạt điện chuyển hoá điện năng thành động năng (cánh quạt), năng lượng âm thanh và nhiệt; pin mặt trời chuyển quang năng thành điện năng.","Định luật bảo toàn năng lượng: Năng lượng không tự sinh ra hoặc tự mất đi mà chỉ chuyển từ dạng này sang dạng khác hoặc truyền từ vật này sang vật khác.","Khi quả bóng rơi, thế năng chuyển…: Khi quả bóng rơi, thế năng chuyển dần thành động năng; khi nảy lên, động năng chuyển thành thế năng."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 49. Năng lượng hao phí","req":["Nêu được năng lượng hao phí luôn xuất hiện khi năng lượng chuyển từ dạng này sang dạng khác."],"sum":["Khi năng lượng chuyển hoá hoặc truyền đi, luôn có một phần năng lượng chuyển thành dạng không mong muốn (thường là nhiệt), gọi là năng lượng hao phí.","Khái niệm: Khi năng lượng chuyển hoá hoặc truyền đi, luôn có một phần năng lượng chuyển thành dạng không mong muốn (thường là nhiệt), gọi là năng lượng hao phí.","Ví dụ: Bóng đèn sợi đốt phần lớn điện năng chuyển thành nhiệt (hao phí), chỉ một phần nhỏ thành ánh sáng;"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 50. Năng lượng tái tạo","req":["Nêu được một số nguồn năng lượng tái tạo, ưu điểm và hạn chế."],"sum":["Năng lượng tái tạo là năng lượng từ những nguồn liên tục được bổ sung theo các quá trình tự nhiên: năng lượng Mặt Trời, gió, nước (thuỷ điện, thuỷ triều), địa nhiệt, sinh khối.","Khái niệm: Năng lượng tái tạo là năng lượng từ những nguồn liên tục được bổ sung theo các quá trình tự nhiên: năng lượng Mặt Trời, gió, nước (thuỷ điện, thuỷ…","Năng lượng không tái tạo (than đá…: Năng lượng không tái tạo (than đá, dầu mỏ, khí đốt) có hạn, sử dụng gây ô nhiễm môi trường và phát thải khí nhà kính.","Ưu điểm của năng lượng tái tạo: Gần như vô tận, ít gây ô nhiễm."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 51. Tiết kiệm năng lượng","req":["Nêu được các biện pháp tiết kiệm năng lượng; ý nghĩa của tiết kiệm năng lượng."],"sum":["Tiết kiệm năng lượng là sử dụng năng lượng hợp lí, hiệu quả, giảm hao phí. Lợi ích: giảm chi phí, bảo vệ tài nguyên, giảm ô nhiễm môi trường.","Khái niệm: Tiết kiệm năng lượng là sử dụng năng lượng hợp lí, hiệu quả, giảm hao phí.","Biện pháp: Tắt thiết bị điện khi không dùng; sử dụng thiết bị tiết kiệm năng lượng (đèn LED, máy có nhãn năng lượng); tận dụng ánh sáng, gió tự nhiên;","Điện năng tiêu thụ (kWh) = công…: Điện năng tiêu thụ (kWh) = công suất (kW) × thời gian sử dụng (h)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương X. Trái Đất và bầu trời","l":[{"t":"Bài 52. Chuyển động nhìn thấy của Mặt Trời. Thiên thể","req":["Giải thích được hiện tượng Mặt Trời mọc, lặn; nêu được khái niệm thiên thể."],"sum":["Thiên thể là các vật thể tự nhiên tồn tại trong không gian vũ trụ như các ngôi sao, hành tinh, vệ tinh, sao chổi…","Khái niệm: Thiên thể là các vật thể tự nhiên tồn tại trong không gian vũ trụ như các ngôi sao, hành tinh, vệ tinh, sao chổi…","Hằng ngày ta thấy Mặt Trời mọc ở phía đông, lặn ở phía tây: Đó là chuyển động nhìn thấy (chuyển động biểu kiến), không phải chuyển động thật của Mặt Trời.","Nguyên nhân: Trái Đất tự quay quanh trục theo hướng từ tây sang đông, một vòng hết khoảng 24 giờ, nên người trên Trái Đất thấy Mặt Trời chuyển động ngược lại từ…"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 53. Mặt Trăng","req":["Giải thích được các pha nhìn thấy của Mặt Trăng."],"sum":["Mặt Trăng là vệ tinh tự nhiên của Trái Đất; Mặt Trăng không tự phát sáng mà phản chiếu ánh sáng Mặt Trời.","Mặt Trăng là vệ tinh tự nhiên của Trái Đất: Mặt Trăng không tự phát sáng mà phản chiếu ánh sáng Mặt Trời.","Vì Mặt Trăng chuyển động quanh Trái…: Vì Mặt Trăng chuyển động quanh Trái Đất, phần được Mặt Trời chiếu sáng mà ta nhìn thấy thay đổi theo ngày, tạo nên các pha: trăng mới (không trăng),…","Ngày rằm (15 âm lịch) thường thấy…: Ngày rằm (15 âm lịch) thường thấy trăng tròn; ngày mùng 1 không thấy trăng."],"e":["Hay nhầm: Chủ yếu là ánh sáng Mặt Trời."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 54. Hệ Mặt Trời","req":["Mô tả được sơ lược cấu trúc hệ Mặt Trời; nêu được các hành tinh chuyển động quanh Mặt Trời."],"sum":["Hệ Mặt Trời gồm Mặt Trời ở trung tâm và các thiên thể chuyển động quanh nó: 8 hành tinh, các vệ tinh, tiểu hành tinh, sao chổi…","Khái niệm: Hệ Mặt Trời gồm Mặt Trời ở trung tâm và các thiên thể chuyển động quanh nó: 8 hành tinh, các vệ tinh, tiểu hành tinh, sao chổi…","Mặt Trời là một ngôi sao, tự phát ra ánh sáng: Các hành tinh không tự phát sáng mà phản xạ ánh sáng Mặt Trời.","Tám hành tinh theo thứ tự xa dần Mặt Trời: Thuỷ tinh, Kim tinh, Trái Đất, Hoả tinh, Mộc tinh, Thổ tinh, Thiên Vương tinh, Hải Vương tinh.","Đơn vị thiên văn (AU) xấp xỉ…: Đơn vị thiên văn (AU) xấp xỉ khoảng cách từ Trái Đất đến Mặt Trời, khoảng 150 triệu km."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 55. Ngân Hà","req":["Nêu được Ngân Hà là tập hợp rất nhiều ngôi sao; hệ Mặt Trời là một phần nhỏ của Ngân Hà."],"sum":["Ngôi sao là thiên thể tự phát sáng. Mặt Trời là một ngôi sao.","Ngôi sao là thiên thể tự phát sáng: Mặt Trời là một ngôi sao.","Ngân Hà là thiên hà chứa hệ…: Ngân Hà là thiên hà chứa hệ Mặt Trời, gồm hàng trăm tỉ ngôi sao.","Chòm sao là nhóm các ngôi sao…: Chòm sao là nhóm các ngôi sao nhìn thấy gần nhau trên bầu trời, tạo thành hình dạng xác định (chòm Gấu Lớn, Thiên Hậu, Lạp Hộ…)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]}]},{"t":"Bài tập nâng cao","c":[{"t":"Chương I. Mở đầu về Khoa học tự nhiên","l":[{"t":"Bài tập nâng cao · Chương I. Mở đầu về Khoa học tự nhiên (12 câu)","e":["Hay nhầm: Phải tiếp xúc, đo môi trường."],"q":{"n":12,"lv":{"Nâng cao":12}}}]},{"t":"Chương VIII. Lực trong đời sống","l":[{"t":"Bài tập nâng cao · Chương VIII. Lực trong đời sống (10 câu)","e":["Hay nhầm: Không phải nguyên nhân chính."],"q":{"n":10,"lv":{"Nâng cao":10}}}]},{"t":"Chương IX. Năng lượng","l":[{"t":"Bài tập nâng cao · Chương IX. Năng lượng (12 câu)","e":["Hay nhầm: Bằng 0 (chọn mặt đất làm mốc)."],"q":{"n":12,"lv":{"Nâng cao":12}}}]},{"t":"Chương X. Trái Đất và bầu trời","l":[{"t":"Bài tập nâng cao · Chương X. Trái Đất và bầu trời (8 câu)","q":{"n":8,"lv":{"Nâng cao":8}}}]}]}]},{"id":"hoa","name":"Hoá học","b":[{"t":"Hoá học 6","c":[{"t":"Chương II. Chất quanh ta","l":[{"t":"Bài 9. Sự đa dạng của chất","req":["Nêu được sự đa dạng của chất; phân biệt vật thể tự nhiên, vật thể nhân tạo, vật sống, vật không sống; nêu được tính chất vật lí, tính chất hoá học của chất."],"sum":["Chất có ở xung quanh ta, ở đâu có vật thể ở đó có chất. Vật thể tự nhiên có sẵn trong tự nhiên (cây, đá, nước biển); vật thể nhân tạo do con người tạo ra (bàn, ghế, xe đạp).","Chất có ở xung quanh ta, ở đâu có vật thể ở đó có chất: Vật thể tự nhiên có sẵn trong tự nhiên (cây, đá, nước biển); vật thể nhân tạo do con người tạo ra (bàn, ghế, xe đạp).","Mỗi chất có những tính chất nhất định: Tính chất vật lí: thể (rắn, lỏng, khí), màu sắc, mùi vị, tính tan, tính dẫn điện, dẫn nhiệt, nhiệt độ sôi, nhiệt độ nóng chảy, khối lượng riêng.","Tính chất hoá học là khả năng chất bị biến đổi thành chất khác, ví dụ: Bị phân huỷ, tác dụng với chất khác, khả năng cháy."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 10. Các thể của chất và sự chuyển thể","req":["Nêu được các thể của chất và đặc điểm; trình bày được các quá trình chuyển thể: nóng chảy, đông đặc, bay hơi, ngưng tụ, sôi."],"sum":["Chất tồn tại ở ba thể chính: rắn, lỏng, khí. Thể rắn: các hạt liên kết chặt, có hình dạng và thể tích xác định, rất khó nén.","Chất tồn tại ở ba thể chính: Rắn, lỏng, khí.","Sự nóng chảy là sự chuyển từ…: Sự nóng chảy là sự chuyển từ thể rắn sang thể lỏng; sự đông đặc là chuyển từ lỏng sang rắn.","Sự bay hơi là sự chuyển từ…: Sự bay hơi là sự chuyển từ thể lỏng sang thể hơi (xảy ra ở bề mặt chất lỏng, ở mọi nhiệt độ); sự ngưng tụ là chuyển từ thể hơi sang thể lỏng."],"e":["Hay nhầm: Không có hình dạng xác định.","Hay nhầm: Không có hình dạng, thể tích xác định."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 11. Oxygen. Không khí","req":["Nêu được tính chất vật lí, tầm quan trọng của oxygen; thành phần không khí; vai trò của không khí; nguyên nhân và biện pháp chống ô nhiễm không khí."],"sum":["Oxygen là chất khí không màu, không mùi, không vị, ít tan trong nước, nặng hơn không khí. Ở −183 °C oxygen hoá lỏng có màu xanh nhạt.","Khái niệm: Oxygen là chất khí không màu, không mùi, không vị, ít tan trong nước, nặng hơn không khí.","Oxygen duy trì sự sống (hô hấp)…: Oxygen duy trì sự sống (hô hấp) và sự cháy; dùng trong y tế, hàn cắt kim loại, du hành vũ trụ.","Không khí là hỗn hợp khí: Nitrogen khoảng 78%, oxygen khoảng 21%, còn lại khoảng 1% là carbon dioxide, hơi nước, khí hiếm…","Ô nhiễm không khí do khói xe…: Ô nhiễm không khí do khói xe, khí thải nhà máy, đốt rác, cháy rừng… gây bệnh hô hấp, mưa acid, hiệu ứng nhà kính."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương III. Một số vật liệu, nguyên liệu, nhiên liệu, lương thực – thực phẩm thông dụng","l":[{"t":"Bài 12. Một số vật liệu","req":["Trình bày được tính chất và ứng dụng của một số vật liệu thông dụng; sử dụng vật liệu an toàn, hiệu quả, bảo đảm phát triển bền vững."],"sum":["Vật liệu là chất hoặc hỗn hợp chất được dùng trong xây dựng, sản xuất, chế tạo… Một số vật liệu thông dụng: kim loại, nhựa, cao su, gỗ, thuỷ tinh, gốm, sứ.","Khái niệm: Vật liệu là chất hoặc hỗn hợp chất được dùng trong xây dựng, sản xuất, chế tạo… Một số vật liệu thông dụng: kim loại, nhựa, cao su, gỗ, thuỷ tinh,…","Kim loại dẫn điện, dẫn nhiệt tốt…: Kim loại dẫn điện, dẫn nhiệt tốt, dễ uốn; dùng làm dây điện, nồi, xoong; dễ bị gỉ (sắt).","Sử dụng vật liệu hiệu quả: Chọn vật liệu phù hợp mục đích; tái chế, tái sử dụng; hạn chế nhựa dùng một lần để bảo vệ môi trường."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 13. Một số nguyên liệu","req":["Trình bày được tính chất và ứng dụng của một số nguyên liệu thông dụng; sử dụng nguyên liệu an toàn, hiệu quả, bền vững."],"sum":["Nguyên liệu là vật liệu tự nhiên (vật liệu thô) chưa qua xử lí, cần chế biến để tạo ra sản phẩm.","Khái niệm: Nguyên liệu là vật liệu tự nhiên (vật liệu thô) chưa qua xử lí, cần chế biến để tạo ra sản phẩm.","Đá vôi có thành phần chính là…: Đá vôi có thành phần chính là calcium carbonate, bị phân huỷ khi nung tạo vôi sống; dùng trong xây dựng, sản xuất xi măng, vôi.","Quặng là đất đá chứa khoáng chất…: Quặng là đất đá chứa khoáng chất có ích với hàm lượng đủ lớn để khai thác."],"e":["Hay nhầm: Nguyên liệu xi măng, vôi."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 14. Một số nhiên liệu","req":["Trình bày được tính chất và ứng dụng của một số nhiên liệu; sử dụng nhiên liệu an toàn, hiệu quả, bền vững."],"sum":["Nhiên liệu là những chất cháy được, khi cháy toả nhiệt và phát sáng. Phân loại: nhiên liệu rắn (than, củi), lỏng (xăng, dầu, cồn), khí (khí thiên nhiên, khí gas, biogas).","Khái niệm: Nhiên liệu là những chất cháy được, khi cháy toả nhiệt và phát sáng.","Sử dụng nhiên liệu hiệu quả: Cung cấp đủ oxygen (không khí) cho sự cháy; tăng diện tích tiếp xúc của nhiên liệu với không khí (chẻ nhỏ củi, đập nhỏ than);","Nhiên liệu hoá thạch (than, dầu, khí)…: Nhiên liệu hoá thạch (than, dầu, khí) có hạn và gây ô nhiễm; cần tiết kiệm và phát triển nhiên liệu thay thế như xăng sinh học E5, biogas, năng…"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 15. Một số lương thực, thực phẩm","req":["Trình bày được tính chất và ứng dụng của một số lương thực, thực phẩm; vai trò của các nhóm chất dinh dưỡng."],"sum":["Lương thực là thức ăn chứa hàm lượng lớn tinh bột (gạo, ngô, khoai, sắn, lúa mì). Thực phẩm là sản phẩm con người ăn, uống ở dạng tươi sống hoặc đã chế biến.","Khái niệm: Lương thực là thức ăn chứa hàm lượng lớn tinh bột (gạo, ngô, khoai, sắn, lúa mì).","Các nhóm chất dinh dưỡng: Carbohydrate (cung cấp năng lượng chủ yếu), protein (xây dựng, tái tạo tế bào), lipid (chất béo – dự trữ năng lượng, hoà tan vitamin), vitamin và…","Cần ăn uống đa dạng, cân đối…: Cần ăn uống đa dạng, cân đối; bảo quản thực phẩm đúng cách (để lạnh, phơi khô, muối, đóng hộp) và chọn thực phẩm an toàn, rõ nguồn gốc."],"e":["Hay nhầm: Không phải chất dinh dưỡng chính."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương IV. Hỗn hợp. Tách chất ra khỏi hỗn hợp","l":[{"t":"Bài 16. Hỗn hợp các chất","req":["Phân biệt chất tinh khiết, hỗn hợp; hỗn hợp đồng nhất, không đồng nhất; dung dịch, huyền phù, nhũ tương; chất tan và yếu tố ảnh hưởng đến lượng chất tan."],"sum":["Chất tinh khiết (chất nguyên chất) được tạo ra từ một chất duy nhất, có tính chất xác định (nước cất).","Khái niệm: Chất tinh khiết (chất nguyên chất) được tạo ra từ một chất duy nhất, có tính chất xác định (nước cất).","Hỗn hợp đồng nhất có thành phần…: Hỗn hợp đồng nhất có thành phần giống nhau ở mọi vị trí (nước đường).","Dung dịch là hỗn hợp đồng nhất của dung môi và chất tan: Huyền phù là hỗn hợp chất rắn lơ lửng trong chất lỏng; nhũ tương là hỗn hợp chất lỏng phân tán trong chất lỏng khác (dầu trộn nước).","Lượng chất tan tan được trong nước…: Lượng chất tan tan được trong nước phụ thuộc vào loại chất và nhiệt độ; khuấy, đun nóng giúp chất rắn tan nhanh hơn."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 17. Tách chất khỏi hỗn hợp","req":["Trình bày được một số cách tách chất ra khỏi hỗn hợp: lọc, cô cạn, chiết; ứng dụng trong thực tế."],"sum":["Tách chất dựa vào sự khác nhau về tính chất vật lí của các chất trong hỗn hợp (kích thước hạt, tính tan, nhiệt độ sôi, khối lượng riêng…).","Khái niệm: Tách chất dựa vào sự khác nhau về tính chất vật lí của các chất trong hỗn hợp (kích thước hạt, tính tan, nhiệt độ sôi, khối lượng riêng…).","Lọc: Tách chất rắn không tan ra khỏi chất lỏng (tách cát khỏi nước).","Ứng dụng: Lọc nước sinh hoạt, làm muối từ nước biển, tách dầu mỏ, chưng cất rượu."],"e":["Hay nhầm: Muối tan, lọt qua giấy lọc."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]}]},{"t":"Bài tập nâng cao","c":[{"t":"Chương II. Chất quanh ta","l":[{"t":"Bài tập nâng cao · Chương II. Chất quanh ta (6 câu)","e":["Hay nhầm: Không phải nguyên nhân chính.","Hay nhầm: Không phải nguyên nhân chính.","Hay nhầm: Không phải nguyên nhân chính."],"q":{"n":6,"lv":{"Nâng cao":6}}}]},{"t":"Chương III. Một số vật liệu, nguyên liệu, nhiên liệu, lương thực – thực phẩm thông dụng","l":[{"t":"Bài tập nâng cao · Chương III. Một số vật liệu, nguyên liệu, nhiên liệu, lương thực – thực phẩm thông dụng (8 câu)","e":["Hay nhầm: Không phải nguy hiểm chính."],"q":{"n":8,"lv":{"Nâng cao":8}}}]},{"t":"Chương IV. Hỗn hợp. Tách chất ra khỏi hỗn hợp","l":[{"t":"Bài tập nâng cao · Chương IV. Hỗn hợp. Tách chất ra khỏi hỗn hợp (4 câu)","q":{"n":4,"lv":{"Nâng cao":4}}}]}]}]},{"id":"sinh","name":"Sinh học","b":[{"t":"Sinh học 6","c":[{"t":"Mở đầu","l":[{"t":"Bài 3. Sử dụng kính lúp","req":["Trình bày được cấu tạo và cách sử dụng kính lúp."],"sum":["Kính lúp là dụng cụ quan sát vật nhỏ, có độ phóng đại từ 3 đến 20 lần. Cấu tạo gồm tấm kính lồi (mặt kính) và tay cầm (khung).","Khái niệm: Kính lúp là dụng cụ quan sát vật nhỏ, có độ phóng đại từ 3 đến 20 lần.","Cách sử dụng: Tay trái cầm kính, để mặt kính sát vật mẫu, mắt nhìn vào mặt kính; từ từ điều chỉnh khoảng cách giữa kính và vật cho đến khi nhìn rõ vật.","Bảo quản: Không để mặt kính tiếp xúc vật cứng, ráp; lau kính bằng khăn mềm; cất nơi khô ráo."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 4. Sử dụng kính hiển vi quang học","req":["Trình bày được cấu tạo và cách sử dụng kính hiển vi quang học."],"sum":["Kính hiển vi quang học có độ phóng đại từ 40 đến 3 000 lần, dùng quan sát những vật rất nhỏ như tế bào, vi khuẩn.","Khái niệm: Kính hiển vi quang học có độ phóng đại từ 40 đến 3 000 lần, dùng quan sát những vật rất nhỏ như tế bào, vi khuẩn.","Cấu tạo gồm: Hệ thống giá đỡ (chân kính, thân kính, bàn kính, kẹp giữ mẫu), hệ thống phóng đại (thị kính, vật kính), hệ thống chiếu sáng (nguồn sáng, gương, màn…","Cách sử dụng: Chuẩn bị kính;"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương V. Tế bào","l":[{"t":"Bài 18. Tế bào – Đơn vị cơ bản của sự sống","req":["Nêu được khái niệm tế bào, chức năng của tế bào; hình dạng và kích thước một số loại tế bào."],"sum":["Tế bào là đơn vị cấu trúc và chức năng của cơ thể sống. Mọi cơ thể sống đều được cấu tạo từ một hoặc nhiều tế bào; tế bào thực hiện các quá trình sống cơ bản (trao đổi chất, sinh trưởng, sinh sản,…","Tế bào là đơn vị cấu trúc và chức năng của cơ thể sống: Mọi cơ thể sống đều được cấu tạo từ một hoặc nhiều tế bào; tế bào thực hiện các quá trình sống cơ bản (trao đổi chất, sinh trưởng, sinh sản, cảm ứng).","Tế bào có nhiều hình dạng (hình…: Tế bào có nhiều hình dạng (hình cầu, hình đĩa, hình sợi, hình sao, hình trụ…) và kích thước khác nhau.","Đơn vị đo kích thước tế bào thường dùng: Micrômét (µm);"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 19. Cấu tạo và chức năng các thành phần của tế bào","req":["Trình bày được cấu tạo và chức năng các thành phần chính của tế bào; phân biệt tế bào nhân sơ – nhân thực, tế bào động vật – thực vật."],"sum":["Tế bào có ba thành phần chính: màng tế bào (bao bọc, kiểm soát sự vận chuyển chất ra vào), chất tế bào (nơi diễn ra phần lớn hoạt động sống), nhân hoặc vùng nhân (chứa vật chất di truyền, điều khiển…","Tế bào có ba thành phần chính: Màng tế bào (bao bọc, kiểm soát sự vận chuyển chất ra vào), chất tế bào (nơi diễn ra phần lớn hoạt động sống), nhân hoặc vùng nhân (chứa vật chất di…","Tế bào nhân sơ chưa có màng…: Tế bào nhân sơ chưa có màng nhân, vật chất di truyền nằm ở vùng nhân (vi khuẩn).","Tế bào thực vật có thành tế…: Tế bào thực vật có thành tế bào (bảo vệ, tạo hình dạng) và lục lạp (quang hợp); tế bào động vật không có thành tế bào và lục lạp."],"e":["Hay nhầm: Nơi diễn ra hoạt động sống."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 20. Sự lớn lên và sinh sản của tế bào","req":["Mô tả sự lớn lên và sinh sản của tế bào; ý nghĩa của sự lớn lên và sinh sản."],"sum":["Tế bào lớn lên nhờ quá trình trao đổi chất, tăng dần kích thước. Khi đạt kích thước nhất định, tế bào thực hiện sinh sản (phân chia).","Khái niệm: Tế bào lớn lên nhờ quá trình trao đổi chất, tăng dần kích thước.","Quá trình phân chia: Đầu tiên nhân phân chia, sau đó chất tế bào phân chia, hình thành hai tế bào con.","Ý nghĩa: Sự lớn lên và sinh sản của tế bào giúp cơ thể lớn lên (tăng kích thước, khối lượng) và thay thế các tế bào già, chết, bị tổn thương."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương VI. Từ tế bào đến cơ thể","l":[{"t":"Bài 22. Cơ thể sinh vật","req":["Phân biệt vật sống và vật không sống; nhận biết cơ thể đơn bào và cơ thể đa bào."],"sum":["Cơ thể sinh vật là một vật sống, có các quá trình sống cơ bản: cảm ứng và vận động, sinh trưởng, sinh sản, hô hấp, bài tiết, dinh dưỡng.","Cơ thể sinh vật là một vật sống, có các quá trình sống cơ bản: Cảm ứng và vận động, sinh trưởng, sinh sản, hô hấp, bài tiết, dinh dưỡng.","Cơ thể đơn bào được cấu tạo…: Cơ thể đơn bào được cấu tạo từ một tế bào; tế bào đó thực hiện mọi chức năng sống (vi khuẩn, trùng roi, tảo lục đơn bào, nấm men).","Cơ thể đa bào được cấu tạo…: Cơ thể đa bào được cấu tạo từ nhiều tế bào; mỗi loại tế bào thực hiện chức năng khác nhau (cây xoài, con chó, con người, nấm rơm)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 23. Tổ chức cơ thể đa bào","req":["Nêu được các cấp độ tổ chức trong cơ thể đa bào: tế bào – mô – cơ quan – hệ cơ quan – cơ thể."],"sum":["Mô là tập hợp các tế bào giống nhau cùng thực hiện một chức năng nhất định (mô cơ, mô thần kinh, mô biểu bì, mô dẫn ở thực vật).","Khái niệm: Mô là tập hợp các tế bào giống nhau cùng thực hiện một chức năng nhất định (mô cơ, mô thần kinh, mô biểu bì, mô dẫn ở thực vật).","Cơ quan được cấu tạo từ nhiều…: Cơ quan được cấu tạo từ nhiều mô khác nhau, cùng thực hiện một chức năng (tim, dạ dày, lá, rễ).","Ở thực vật có hai hệ cơ quan: Hệ chồi (thân, lá, hoa, quả) và hệ rễ."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương VII. Đa dạng thế giới sống","l":[{"t":"Bài 25. Hệ thống phân loại sinh vật","req":["Nêu được sự cần thiết của phân loại thế giới sống; các bậc phân loại; năm giới sinh vật; cách gọi tên sinh vật."],"sum":["Phân loại thế giới sống giúp gọi đúng tên sinh vật, đưa sinh vật vào đúng nhóm phân loại, thấy được sự đa dạng và mối quan hệ giữa các sinh vật.","Khái niệm: Phân loại thế giới sống giúp gọi đúng tên sinh vật, đưa sinh vật vào đúng nhóm phân loại, thấy được sự đa dạng và mối quan hệ giữa các sinh vật.","Các bậc phân loại từ thấp đến cao: Loài → Chi (giống) → Họ → Bộ → Lớp → Ngành → Giới.","Hệ thống năm giới: Khởi sinh (vi khuẩn – nhân sơ), Nguyên sinh, Nấm, Thực vật, Động vật.","Mỗi sinh vật có tên khoa học…: Mỗi sinh vật có tên khoa học gồm tên chi (viết hoa chữ cái đầu) và tên loài, viết in nghiêng, ví dụ Homo sapiens (người)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 26. Khoá lưỡng phân","req":["Nhận biết khoá lưỡng phân; xây dựng được khoá lưỡng phân đơn giản."],"sum":["Khoá lưỡng phân là cách phân loại sinh vật dựa trên một đặc điểm đối lập để chia chúng thành hai nhóm.","Khái niệm: Khoá lưỡng phân là cách phân loại sinh vật dựa trên một đặc điểm đối lập để chia chúng thành hai nhóm.","Cách xây dựng: Liệt kê đặc điểm của từng sinh vật; chọn một đặc điểm để chia sinh vật thành hai nhóm (có – không có); tiếp tục chia mỗi nhóm cho đến khi xác định…","Với n sinh vật, khoá lưỡng phân…: Với n sinh vật, khoá lưỡng phân cần n − 1 bước phân chia (mỗi bước một cặp đặc điểm đối lập)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 27. Vi khuẩn","req":["Mô tả hình dạng, cấu tạo vi khuẩn; vai trò, tác hại; một số bệnh do vi khuẩn và biện pháp phòng tránh."],"sum":["Vi khuẩn là sinh vật đơn bào, nhân sơ, kích thước rất nhỏ (khoảng 0,5–10 µm). Hình dạng: hình cầu, hình que, hình xoắn, hình dấu phẩy.","Khái niệm: Vi khuẩn là sinh vật đơn bào, nhân sơ, kích thước rất nhỏ (khoảng 0,5–10 µm).","Vai trò: Phân giải xác sinh vật, làm sạch môi trường; cố định đạm; chế biến thực phẩm (sữa chua, dưa muối, nước mắm); sản xuất thuốc kháng sinh.","Tác hại: Gây bệnh cho người (lao, tả, thương hàn, uốn ván, tiêu chảy), động vật, thực vật; làm hỏng thức ăn.","Phòng bệnh: Ăn chín uống sôi, rửa tay, vệ sinh môi trường, tiêm vaccine, dùng kháng sinh đúng chỉ định."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 29. Virus","req":["Mô tả hình dạng, cấu tạo đơn giản của virus; vai trò, tác hại; một số bệnh do virus và biện pháp phòng tránh."],"sum":["Virus có kích thước rất nhỏ (khoảng 20–300 nm), chỉ quan sát được bằng kính hiển vi điện tử.","Khái niệm: Virus có kích thước rất nhỏ (khoảng 20–300 nm), chỉ quan sát được bằng kính hiển vi điện tử.","Hình dạng: Dạng xoắn (virus khảm thuốc lá), dạng khối (virus adeno), dạng hỗn hợp (thể thực khuẩn).","Virus sống kí sinh bắt buộc trong…: Virus sống kí sinh bắt buộc trong tế bào sống; ngoài tế bào chúng không biểu hiện sự sống.","Bệnh do virus: Cúm, sởi, thuỷ đậu, quai bị, COVID-19, viêm gan B, sốt xuất huyết, HIV/AIDS."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 30. Nguyên sinh vật","req":["Nhận biết nguyên sinh vật; vai trò và tác hại; một số bệnh do nguyên sinh vật và cách phòng tránh."],"sum":["Nguyên sinh vật là nhóm sinh vật có cấu tạo tế bào nhân thực, kích thước hiển vi; đa số là cơ thể đơn bào (trùng roi, trùng giày, trùng biến hình), một số đa bào (tảo).","Khái niệm: Nguyên sinh vật là nhóm sinh vật có cấu tạo tế bào nhân thực, kích thước hiển vi;","Hình dạng đa dạng: Hình cầu, hình thoi, hình giày, hoặc không có hình dạng cố định (trùng biến hình).","Vai trò: Cung cấp oxygen, là thức ăn cho động vật thuỷ sinh; dùng làm thực phẩm (tảo xoắn).","Phòng bệnh sốt rét: Diệt muỗi, ngủ màn, phát quang bụi rậm."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 32. Nấm","req":["Nhận biết nấm qua hình ảnh; đặc điểm cấu tạo; vai trò và tác hại; một số bệnh do nấm."],"sum":["Nấm là sinh vật nhân thực, đơn bào (nấm men) hoặc đa bào (nấm rơm, nấm mốc). Tế bào nấm có thành tế bào nhưng không có lục lạp nên sống dị dưỡng (hoại sinh, kí sinh hoặc cộng sinh).","Khái niệm: Nấm là sinh vật nhân thực, đơn bào (nấm men) hoặc đa bào (nấm rơm, nấm mốc).","Nấm đa bào thường gồm hệ sợi…: Nấm đa bào thường gồm hệ sợi nấm; nấm lớn có cơ quan sinh sản là mũ nấm, sinh sản bằng bào tử.","Vai trò: Làm thực phẩm (nấm rơm, nấm hương, mộc nhĩ); làm thuốc (linh chi, đông trùng hạ thảo, penicillin từ nấm Penicillium); chế biến thực phẩm (nấm men…","Tác hại: Gây bệnh ở người (hắc lào, lang ben, nấm da), thực vật (đạo ôn, gỉ sắt), làm hỏng thực phẩm; một số nấm độc (nấm độc đen, nấm tán bay)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 34. Thực vật","req":["Phân biệt các nhóm thực vật: rêu, dương xỉ, hạt trần, hạt kín; vai trò của thực vật."],"sum":["Thực vật là sinh vật nhân thực, đa bào, có lục lạp, tự tổng hợp chất hữu cơ nhờ quang hợp.","Khái niệm: Thực vật là sinh vật nhân thực, đa bào, có lục lạp, tự tổng hợp chất hữu cơ nhờ quang hợp.","Rêu: Chưa có mạch dẫn, chưa có rễ thật, sống nơi ẩm ướt, sinh sản bằng bào tử.","Hạt trần: Có mạch dẫn, có hạt nhưng hạt không được bao bọc trong quả (thông, vạn tuế).","Vai trò: Cung cấp oxygen, thức ăn, gỗ, thuốc;"],"e":["Hay nhầm: Dương xỉ, hạt trần cũng có."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 36. Động vật","req":["Phân biệt nhóm động vật không xương sống và có xương sống; đại diện các ngành, lớp; vai trò và tác hại của động vật."],"sum":["Động vật là sinh vật nhân thực, đa bào, sống dị dưỡng, có khả năng di chuyển. Chia thành hai nhóm: không xương sống và có xương sống.","Khái niệm: Động vật là sinh vật nhân thực, đa bào, sống dị dưỡng, có khả năng di chuyển.","Động vật không xương sống: Ruột khoang (thuỷ tức, sứa, san hô), giun (giun đất, giun đũa, sán), thân mềm (ốc, trai, mực), chân khớp (tôm, cua, nhện, côn trùng).","Động vật có xương sống: Cá, lưỡng cư (ếch, cóc), bò sát (rắn, thằn lằn, rùa), chim, thú (động vật có vú).","Vai trò: Cung cấp thực phẩm, nguyên liệu, làm cảnh, thụ phấn, tiêu diệt sâu hại."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 38. Đa dạng sinh học","req":["Nêu được vai trò của đa dạng sinh học; các nguyên nhân suy giảm và biện pháp bảo vệ đa dạng sinh học."],"sum":["Đa dạng sinh học là sự phong phú về số lượng loài, số cá thể trong loài và môi trường sống.","Khái niệm: Đa dạng sinh học là sự phong phú về số lượng loài, số cá thể trong loài và môi trường sống.","Vai trò: Đối với tự nhiên – duy trì cân bằng hệ sinh thái, điều hoà khí hậu;","Nguyên nhân suy giảm: Phá rừng, săn bắt buôn bán động vật hoang dã, ô nhiễm môi trường, biến đổi khí hậu, du nhập loài ngoại lai.","Biện pháp bảo vệ: Thành lập vườn quốc gia, khu bảo tồn; cấm săn bắt, buôn bán động vật hoang dã; trồng rừng; tuyên truyền nâng cao ý thức; xây dựng Sách Đỏ."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 39. Tìm hiểu sinh vật ngoài thiên nhiên","req":["Thực hiện được các phương pháp tìm hiểu sinh vật ngoài thiên nhiên: quan sát, chụp ảnh, ghi chép, phân loại."],"sum":["Dụng cụ: kính lúp, ống nhòm, máy ảnh, vợt bắt côn trùng, kẹp, lọ đựng mẫu, sổ ghi chép.","Dụng cụ: Kính lúp, ống nhòm, máy ảnh, vợt bắt côn trùng, kẹp, lọ đựng mẫu, sổ ghi chép.","Các bước: Quan sát sinh vật ở môi trường sống; chụp ảnh, ghi chép đặc điểm (hình dạng, màu sắc, nơi sống); dùng khoá lưỡng phân hoặc tài liệu để nhận biết,…","Khi tìm hiểu ngoài thiên nhiên cần đảm bảo an toàn: Không tự ý tách đoàn, không bắt hoặc chạm vào sinh vật lạ, độc; bảo vệ môi trường, không phá cây, bắt động vật bừa bãi."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}}]}]},{"t":"Bài tập nâng cao","c":[{"t":"Mở đầu","l":[{"t":"Bài tập nâng cao · Mở đầu (4 câu)","q":{"n":4,"lv":{"Nâng cao":4}}}]},{"t":"Chương V. Tế bào","l":[{"t":"Bài tập nâng cao · Chương V. Tế bào (6 câu)","q":{"n":6,"lv":{"Nâng cao":6}}}]},{"t":"Chương VI. Từ tế bào đến cơ thể","l":[{"t":"Bài tập nâng cao · Chương VI. Từ tế bào đến cơ thể (4 câu)","q":{"n":4,"lv":{"Nâng cao":4}}}]},{"t":"Chương VII. Đa dạng thế giới sống","l":[{"t":"Bài tập nâng cao · Chương VII. Đa dạng thế giới sống (20 câu)","e":["Hay nhầm: Có tác dụng với vi khuẩn."],"q":{"n":20,"lv":{"Nâng cao":20}}}]}]}]},{"id":"anh","name":"Tiếng Anh","b":[{"t":"Tiếng Anh 6","c":[{"t":"Chủ điểm 1. Our Communities (Cộng đồng của chúng ta)","l":[{"t":"Unit 1. My new school (Trường học mới của em)","req":["Dùng đúng thì hiện tại đơn ở dạng khẳng định, phủ định và nghi vấn.","Dùng trạng từ chỉ tần suất đúng vị trí.","Nói và viết về trường học và hoạt động ở trường."],"sum":["Hiện tại đơn: thói quen, sự thật, lịch trình. he / she / it + V-s/es. Trạng từ tần suất đứng trước V thường, sau be.","Hiện tại đơn: Nói về thói quen, sự thật hiển nhiên và lịch trình. Với I / you / we / they dùng động từ nguyên mẫu; với he / she / it thêm -s hoặc -es.","Cách thêm -s / -es","Trạng từ chỉ tần suất: Trả lời cho câu hỏi How often …?","Cụm hoạt động"],"e":["Sai: She don’t like maths. → Đúng: She doesn’t like maths. (Ngôi he / she / it dùng doesn’t, và động từ sau đó về nguyên mẫu.)","Hay nhầm: Go dùng với I/you/we/they.","Hay nhầm: Going không đứng một mình làm động từ chính ở hiện tại đơn.","Hay nhầm: Are không đi với have trong câu hỏi hiện tại đơn.","Hay nhầm: Is không dùng với you và have.","Hay nhầm: Sometimes là thỉnh thoảng."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 2. My house (Ngôi nhà của em)","req":["Dùng sở hữu cách ’s đúng.","Dùng giới từ chỉ nơi chốn để mô tả vị trí đồ vật.","Nói và viết về ngôi nhà và đồ đạc."],"sum":["Sở hữu: tên / danh từ số ít + ’s; số nhiều có -s chỉ thêm ’. Giới từ nơi chốn: in, on, under, behind, in front of, next to, between, near.","Sở hữu cách ’s: Dùng sau tên riêng và danh từ số ít để chỉ vật thuộc về ai. Danh từ số nhiều tận cùng -s chỉ thêm dấu phẩy trên; số nhiều bất quy tắc thì thêm ’s.","Giới từ chỉ nơi chốn","Hỏi nơi chốn","Phát âm âm cuối -s"],"e":["Hay nhầm: Mums là số nhiều, không có dấu sở hữu.","Hay nhầm: Mums’ dùng cho nhiều mẹ, không hợp ngữ cảnh.","Hay nhầm: Dùng ’s với tên riêng số ít, không dùng s’.","Hay nhầm: Dấu ’s đặt ngay sau tên, trước danh từ.","Hay nhầm: In front of là phía trước.","Hay nhầm: Một người sẽ là parent’s."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 3. My friends (Những người bạn của em)","req":["Dùng đúng thì hiện tại tiếp diễn.","Mô tả ngoại hình và tính cách bằng các tính từ đã học.","Nói và viết về bạn bè."],"sum":["Hiện tại tiếp diễn: am / is / are + V-ing, hành động đang diễn ra. Động từ trạng thái (like, love, know, want) không dùng -ing.","Hiện tại tiếp diễn: Nói về hành động đang diễn ra ngay lúc nói, hoặc kế hoạch gần. Dấu hiệu: now, at the moment, at present, Look!, Listen!","Cách thêm -ing","Động từ trạng thái","Ngoại hình và tính cách: Ngoại hình dùng have / has hoặc be; tính cách dùng be + tính từ.","Phát âm /b/ và /p/"],"e":["Sai: I am liking my friend. → Đúng: I like my friend. (Động từ trạng thái như love, like, know, want không dùng ở tiếp diễn.)","Hay nhầm: Plays là hiện tại đơn ngôi thứ ba.","Hay nhầm: Is không đi với children.","Hay nhầm: Read là nguyên mẫu hoặc quá khứ.","Hay nhầm: Không giữ -e khi thêm -ing.","Hay nhầm: Make không gấp đôi phụ âm."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]},{"t":"Chủ điểm 2. Our Heritage (Di sản của chúng ta)","l":[{"t":"Unit 4. My neighbourhood (Khu phố của em)","req":["Dùng đúng dạng so sánh hơn của tính từ ngắn và tính từ dài.","Nói và viết về khu phố.","Nhận biết các địa điểm trong khu phố."],"sum":["So sánh hơn: tính từ ngắn adj-er + than; tính từ dài more + adj + than; bất quy tắc: good → better, bad → worse.","Tính từ ngắn: So sánh hai người hoặc hai vật. Tính từ một âm tiết, hoặc hai âm tiết tận cùng -y, thêm -er + than.","Quy tắc thêm -er","Tính từ dài: Từ hai âm tiết trở lên, không tận cùng -y, dùng more + adj + than.","Bất quy tắc","Phát âm /ɪ/ và /iː/"],"e":["Sai: This book is more cheaper than that one. → Đúng: This book is cheaper than that one. (Không dùng more cùng với -er.)","Hay nhầm: Tính từ ngắn không dùng more.","Hay nhầm: Không thêm -er vào tính từ dài.","Hay nhầm: Most expensive là so sánh nhất.","Hay nhầm: Expensive thiếu more … than.","Hay nhầm: Big là tính từ ngắn, không dùng more."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 5. Natural wonders of Viet Nam (Các kỳ quan thiên nhiên của Việt Nam)","req":["Phân biệt danh từ đếm được và không đếm được.","Dùng must / mustn’t để nói về điều bắt buộc và điều cấm.","Nói và viết về một kỳ quan thiên nhiên."],"sum":["Đếm được: a / an / many / a few. Không đếm được: much / a little, không -s. must = bắt buộc, mustn’t = cấm, don’t have to = không cần.","Đếm được và không đếm được: Danh từ đếm được có số ít và số nhiều. Danh từ không đếm được không có số nhiều và không dùng a/an.","How many / How much: How many + đếm được số nhiều; How much + không đếm được.","Must và mustn’t: Must (phải) diễn tả điều bắt buộc; mustn’t (không được phép) diễn tả điều cấm. Sau chúng là động từ nguyên mẫu.","Mustn’t và don’t have to","Phát âm /t/ và /d/"],"e":["Hay nhầm: Boat đếm được: a boat, two boats.","Hay nhầm: Much đi với danh từ không đếm được.","Hay nhầm: An đi với danh từ số ít bắt đầu bằng nguyên âm.","Hay nhầm: Don’t không đi với động từ nguyên mẫu như vậy.","Hay nhầm: Can’t not là sai ngữ pháp.","Hay nhầm: Many đi với danh từ đếm được."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 6. Our Tet holiday (Tết của chúng ta)","req":["Dùng should / shouldn’t để khuyên nhủ.","Dùng some / any đúng trong câu khẳng định, phủ định và nghi vấn.","Nói và viết về Tết."],"sum":["should / shouldn’t + V: lời khuyên. some cho câu khẳng định, any cho phủ định và nghi vấn.","Should / shouldn’t: Đưa ra lời khuyên. Sau should luôn là động từ nguyên mẫu, ở mọi ngôi.","Some và any: Chỉ số lượng không xác định, đi với danh từ đếm được số nhiều và không đếm được.","Phát âm /s/ và /ʃ/"],"e":["Sai: She shoulds help her mum. → Đúng: She should help her mum. (Should không thêm -s, và theo sau là V nguyên mẫu.)","Hay nhầm: Shouldn’t to sai cấu trúc.","Hay nhầm: Should là nên, trái nghĩa.","Hay nhầm: Do không đi với động từ nguyên mẫu như vậy.","Hay nhầm: Some dùng trong câu khẳng định.","Hay nhầm: A dùng với danh từ số ít."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]},{"t":"Chủ điểm 3. Our World (Thế giới của chúng ta)","l":[{"t":"Unit 7. Television (Truyền hình)","req":["Dùng đúng các từ để hỏi Wh-.","Dùng and, but, so để nối câu ghép.","Nói và viết về chương trình truyền hình yêu thích."],"sum":["Từ hỏi Wh-: What, Who, Where, When, Why, How… Nối câu: , and (cùng hướng), , but (trái ngược), , so (kết quả).","Từ để hỏi Wh-","And, but, so: Có dấu phẩy trước and / but / so khi nối hai câu hoàn chỉnh. Với so, vế trước là nguyên nhân, vế sau là kết quả.","Phát âm /θ/ và /ð/"],"e":["Hay nhầm: How long hỏi khoảng thời gian.","Hay nhầm: How many hỏi số lượng đếm được.","Hay nhầm: But dùng cho hai ý trái ngược.","Hay nhầm: Because nêu nguyên nhân, không nối hai ý song song.","Hay nhầm: But nối hai ý trái ngược.","Hay nhầm: And nối hai ý cùng hướng nhưng không nêu rõ quan hệ nhân quả."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 8. Sports and games (Thể thao và trò chơi)","req":["Dùng đúng thì quá khứ đơn với động từ có quy tắc và bất quy tắc.","Dùng câu mệnh lệnh khẳng định và phủ định.","Nói và viết về một môn thể thao."],"sum":["Quá khứ đơn: V-ed / V2, phủ định didn’t + V. Be: was / were. Mệnh lệnh: V hoặc Don’t + V.","Quá khứ đơn: Hành động đã xảy ra và kết thúc trong quá khứ. Dấu hiệu: yesterday, last week, in 2020, two days ago.","Thêm -ed và bất quy tắc","Động từ be","Câu mệnh lệnh: Dùng để ra lệnh, yêu cầu, hướng dẫn. Có thể thêm please cho lịch sự.","Phát âm /e/ và /æ/"],"e":["Sai: She didn’t went to the gym. → Đúng: She didn’t go to the gym. (Sau didn’t động từ về nguyên mẫu.)","Hay nhầm: Plays là hiện tại ngôi thứ ba.","Hay nhầm: Goes là hiện tại ngôi thứ ba.","Hay nhầm: Are dùng với be, không với watch.","Hay nhầm: Doesn’t play là hiện tại.","Hay nhầm: Not played không đúng cấu trúc."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 9. Cities of the world (Các thành phố trên thế giới)","req":["Dùng đúng tính từ sở hữu và đại từ sở hữu.","Nói và viết về một thành phố.","Viết một tấm bưu thiếp đơn giản."],"sum":["Tính từ sở hữu đứng trước danh từ (my, your, his…). Đại từ sở hữu đứng một mình (mine, yours, his…).","Tính từ sở hữu: Đứng TRƯỚC danh từ để chỉ vật thuộc về ai: my, your, his, her, its, our, their.","Đại từ sở hữu: Đứng MỘT MÌNH, không có danh từ theo sau; thay cho tính từ sở hữu + danh từ để tránh lặp.","Bảng so sánh","Its và it’s","Phát âm /aʊ/ và /əʊ/"],"e":["Sai: The dog wagged it’s tail. → Đúng: The dog wagged its tail. (its = của nó (không có dấu phẩy trên); it’s = it is. Hers, ours, yours, theirs cũng không có dấu phẩy trên.)","Hay nhầm: My cần có danh từ theo sau.","Hay nhầm: Your cần danh từ theo sau.","Hay nhầm: Her cần danh từ theo sau.","Hay nhầm: Hers không có dấu phẩy trên.","Hay nhầm: It’s là it is hoặc it has."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]},{"t":"Chủ điểm 4. Visions of the Future (Tầm nhìn tương lai)","l":[{"t":"Unit 10. Our houses in the future (Những ngôi nhà trong tương lai)","req":["Dùng will / won’t để dự đoán về tương lai.","Dùng might để nói về khả năng.","Nói và viết về ngôi nhà tương lai."],"sum":["Tương lai đơn: will + V. might + V: có thể, chưa chắc. Will = chắc chắn hơn might.","Tương lai đơn với will: Nói về dự đoán, quyết định ngay lúc nói hoặc lời hứa. Dấu hiệu: tomorrow, next week, in the future, soon, in 2050.","Might: Diễn tả khả năng chưa chắc chắn, thấp hơn will. Phủ định: might not.","Will và might","Trọng âm từ hai âm tiết"],"e":["Sai: She wills go tomorrow. → Đúng: She will go tomorrow. (Sau will là V nguyên mẫu, ở mọi ngôi, không thêm -s.)","Hay nhầm: Are không đi với V nguyên mẫu như vậy.","Hay nhầm: Would dùng trong ngữ cảnh khác.","Hay nhầm: Is không đi với động từ nguyên mẫu.","Hay nhầm: Dishwasher là máy rửa bát.","Hay nhầm: Are không đi với V nguyên mẫu."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 11. Our greener world (Thế giới xanh hơn của chúng ta)","req":["Dùng đúng mạo từ a / an / the.","Dùng câu điều kiện loại 1.","Nói và viết về cách sống xanh."],"sum":["Mạo từ: a / an (chưa xác định), the (đã xác định), không mạo từ (nói chung). Điều kiện 1: If + hiện tại đơn, will + V.","A, an, the: A / an trước danh từ số ít đếm được nhắc lần đầu; a trước phụ âm, an trước nguyên âm. The khi người nói và người nghe đều biết vật nào; không mạo từ…","Câu điều kiện loại 1: Nói về điều có thể xảy ra ở hiện tại hoặc tương lai: nếu điều kiện xảy ra thì kết quả sẽ xảy ra.","Ba chữ R","Nhịp điệu câu: Từ nội dung (danh từ, động từ, tính từ) được nhấn mạnh, từ chức năng (a, the, of, to) đọc nhẹ."],"e":["Sai: If we will recycle paper, we will save trees. → Đúng: If we recycle paper, we will save trees. (Vế If dùng hiện tại đơn, không dùng will.)","Hay nhầm: The dùng khi đã xác định.","Hay nhầm: Some không đi với apple số ít.","Hay nhầm: A dùng cho vật chưa xác định.","Hay nhầm: Cần dùng the với vật duy nhất.","Hay nhầm: Are không đi với V nguyên mẫu."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 12. Robots (Rô-bốt)","req":["Dùng đúng so sánh nhất của tính từ ngắn.","Nói về những việc rô-bốt có thể làm.","Nói và viết về một rô-bốt em muốn có."],"sum":["So sánh nhất tính từ ngắn: the + adj-est. Bất quy tắc: good → the best, bad → the worst. Dùng khi so sánh từ ba đối tượng trở lên.","So sánh nhất: Chỉ người hoặc vật vượt trội nhất trong ba đối tượng trở lên. Luôn có the. Sau đó thường dùng in + nơi chốn / nhóm hoặc of + số nhiều.","Quy tắc thêm -est","So sánh hơn và so sánh nhất","Can / can’t: Nói rô-bốt có thể làm gì.","Ngữ điệu xuống: Thường dùng ở cuối câu kể và câu hỏi Wh-."],"e":["Hay nhầm: Most tall không dùng với tính từ ngắn.","Hay nhầm: Cheap là tính từ ngắn nên không dùng most.","Hay nhầm: Biger thiếu một chữ g và là dạng so sánh hơn.","Hay nhầm: Most big không dùng với tính từ ngắn.","Hay nhầm: Strong là tính từ ngắn nên không dùng most.","Hay nhầm: Cả hai đều so sánh hơn nên sai ở chỗ thứ hai."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]}]}]},{"id":"lichsu","name":"Lịch sử","b":[{"t":"Lịch sử 6","c":[{"t":"Chương 1. Vì sao phải học lịch sử?","l":[{"t":"Bài 1. Lịch sử và cuộc sống","req":["Nêu được khái niệm lịch sử, môn Lịch sử; giải thích được vì sao cần học lịch sử."],"sum":["Lịch sử là những gì đã diễn ra trong quá khứ, bao gồm mọi hoạt động của con người từ khi xuất hiện đến nay.","Khái niệm: Lịch sử là những gì đã diễn ra trong quá khứ, bao gồm mọi hoạt động của con người từ khi xuất hiện đến nay.","Từ khoá cần ghi nhớ: Lịch sử; quá khứ; khoa học lịch sử; cội nguồn; bài học lịch sử.","Mốc sự kiện cần nhớ: Lịch sử là toàn bộ hoạt động của con người từ khi xuất hiện đến nay","Môn Lịch sử là môn học tìm…: Môn Lịch sử là môn học tìm hiểu về lịch sử loài người, bao gồm toàn bộ những hoạt động của con người và xã hội loài người trong quá khứ.","Học lịch sử để biết được cội…: Học lịch sử để biết được cội nguồn của bản thân, gia đình, dòng họ, dân tộc và cả loài người; hiểu được ông cha ta đã lao động, sáng tạo, đấu tranh…"],"e":["Hay nhầm: Bao gồm mọi hoạt động của con người."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 2. Dựa vào đâu để biết và phục dựng lại lịch sử?","req":["Phân biệt các nguồn sử liệu: truyền miệng, chữ viết, hiện vật, gốc và phái sinh."],"sum":["Tư liệu truyền miệng là những câu chuyện, lời kể truyền từ đời này sang đời khác (truyền thuyết, ca dao, tục ngữ).","Khái niệm: Tư liệu truyền miệng là những câu chuyện, lời kể truyền từ đời này sang đời khác (truyền thuyết, ca dao, tục ngữ).","Từ khoá cần ghi nhớ: Tư liệu truyền miệng; tư liệu hiện vật; tư liệu chữ viết; tư liệu gốc; tư liệu gián tiếp; phục dựng lịch sử.","Mốc sự kiện cần nhớ: Ba loại tư liệu chính: truyền miệng, hiện vật, chữ viết","Tư liệu hiện vật là những di…: Tư liệu hiện vật là những di tích, đồ vật của người xưa còn giữ lại trong lòng đất hay trên mặt đất (trống đồng, đồ gốm, công cụ đá).","Tư liệu chữ viết là những bản…: Tư liệu chữ viết là những bản ghi, sách được in, khắc bằng chữ viết, vở chép tay… từ quá khứ còn được lưu lại (bia đá, sắc phong, sách sử)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 3. Thời gian trong lịch sử","req":["Nêu được một số khái niệm thời gian: thập kỉ, thế kỉ, thiên niên kỉ, trước Công nguyên, Công nguyên, âm lịch, dương lịch; tính được thời gian các sự kiện."],"sum":["Âm lịch là cách tính thời gian theo chu kì Mặt Trăng quay quanh Trái Đất; dương lịch tính theo chu kì Trái Đất quay quanh Mặt Trời.","Khái niệm: Âm lịch là cách tính thời gian theo chu kì Mặt Trăng quay quanh Trái Đất; dương lịch tính theo chu kì Trái Đất quay quanh Mặt Trời.","Từ khoá cần ghi nhớ: Âm lịch; dương lịch; công lịch;","Mốc sự kiện cần nhớ: Năm 1 CN là năm tương truyền Chúa Giê-su ra đời; không có năm 0; thế kỉ I tính từ năm 1 đến năm 100","Công lịch lấy năm tương truyền Chúa…: Công lịch lấy năm tương truyền Chúa Giê-su ra đời làm năm 1 Công nguyên (CN); trước đó là trước Công nguyên (TCN).","Một thập kỉ là 10 năm; một…: Một thập kỉ là 10 năm; một thế kỉ là 100 năm; một thiên niên kỉ là 1 000 năm."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương 2. Thời kì nguyên thuỷ","l":[{"t":"Bài 4. Nguồn gốc loài người","req":["Giới thiệu được sơ lược quá trình tiến hoá từ vượn người thành người; dấu tích người tối cổ ở Đông Nam Á và Việt Nam."],"sum":["Loài người có nguồn gốc từ một loài vượn người sống cách đây khoảng 5–6 triệu năm. Quá trình tiến hoá: Vượn người → Người tối cổ (khoảng 4 triệu năm trước) → Người tinh khôn (khoảng 150 000 năm…","Khái niệm: Loài người có nguồn gốc từ một loài vượn người sống cách đây khoảng 5–6 triệu năm.","Từ khoá cần ghi nhớ: Vượn người;","Mốc sự kiện cần nhớ: Khoảng 5–6 triệu năm trước: vượn người; khoảng 4 triệu năm trước: Người tối cổ; khoảng 150 000 năm trước: Người tinh khôn","Người tối cổ đã đi đứng bằng…: Người tối cổ đã đi đứng bằng hai chân, hai chi trước trở thành hai tay, biết chế tạo công cụ lao động.","Ở Đông Nam Á: Tìm thấy di cốt người tối cổ ở Gia-va (In-đô-nê-xi-a), Pê-rắc (Ma-lai-xi-a)… Ở Việt Nam: răng người tối cổ ở hang Thẩm Khuyên, Thẩm Hai (Lạng Sơn);…"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 5. Xã hội nguyên thuỷ","req":["Mô tả sơ lược các giai đoạn tiến triển của xã hội nguyên thuỷ; đời sống vật chất và tinh thần của người nguyên thuỷ."],"sum":["Xã hội nguyên thuỷ trải qua hai giai đoạn: bầy người nguyên thuỷ (Người tối cổ, sống theo bầy, có người đứng đầu) và công xã thị tộc (Người tinh khôn, gồm các gia đình có quan hệ huyết thống; nhiều…","Xã hội nguyên thuỷ trải qua hai giai đoạn: Bầy người nguyên thuỷ (Người tối cổ, sống theo bầy, có người đứng đầu) và công xã thị tộc (Người tinh khôn, gồm các gia đình có quan hệ huyết thống;…","Từ khoá cần ghi nhớ: Bầy người nguyên thuỷ; công xã thị tộc; bộ lạc; làm chung, hưởng chung; trồng trọt; chăn nuôi.","Mốc sự kiện cần nhớ: Hai giai đoạn: bầy người nguyên thuỷ (Người tối cổ) rồi công xã thị tộc (Người tinh khôn)","Đặc điểm công xã thị tộc: Làm chung, hưởng chung, tôn trọng và bình đẳng; tài sản là của chung.","Đời sống vật chất: Chế tạo công cụ đá, biết dùng lửa, săn bắt, hái lượm, sau đó trồng trọt, chăn nuôi; sống trong hang động, mái đá, rồi dựng lều."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 6. Sự chuyển biến và phân hoá của xã hội nguyên thuỷ","req":["Trình bày được quá trình phát hiện kim loại và vai trò đối với sự chuyển biến, phân hoá xã hội; sự tan rã của xã hội nguyên thuỷ."],"sum":["Khoảng thiên niên kỉ IV TCN, con người phát hiện ra đồng đỏ, sau đó đồng thau; khoảng đầu thiên niên kỉ I TCN biết chế tạo đồ sắt.","Khái niệm: Khoảng thiên niên kỉ IV TCN, con người phát hiện ra đồng đỏ, sau đó đồng thau; khoảng đầu thiên niên kỉ I TCN biết chế tạo đồ sắt.","Từ khoá cần ghi nhớ: Đồng đỏ;","Mốc sự kiện cần nhớ: Khoảng thiên niên kỉ IV TCN: đồng đỏ;","Công cụ kim loại giúp khai hoang…: Công cụ kim loại giúp khai hoang, mở rộng diện tích, tăng năng suất; xuất hiện sản phẩm dư thừa.","Gia đình phụ hệ thay thế gia…: Gia đình phụ hệ thay thế gia đình mẫu hệ; công xã thị tộc tan rã, thay bằng công xã nông thôn."],"e":["Hay nhầm: Không phải công cụ chính."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương 3. Xã hội cổ đại","l":[{"t":"Bài 7. Ai Cập và Lưỡng Hà cổ đại","req":["Nêu được tác động của điều kiện tự nhiên đến sự hình thành nền văn minh Ai Cập, Lưỡng Hà; quá trình thành lập nhà nước; thành tựu văn hoá."],"sum":["Ai Cập nằm ở Đông Bắc châu Phi, có sông Nin; Lưỡng Hà nằm giữa hai con sông Ơ-phrát và Ti-grơ (Tây Á).","Ai Cập nằm ở Đông Bắc châu Phi, có sông Nin: Lưỡng Hà nằm giữa hai con sông Ơ-phrát và Ti-grơ (Tây Á).","Từ khoá cần ghi nhớ: Sông Nin;","Mốc sự kiện cần nhớ: Khoảng năm 3200 TCN, vua Mê-nét thống nhất Ai Cập; thiên niên kỉ IV TCN, người Xu-me lập thành bang","Khoảng năm 3200 TCN, vua Mê-nét thống…: Khoảng năm 3200 TCN, vua Mê-nét thống nhất Ai Cập; người đứng đầu là Pha-ra-ông.","Thành tựu Ai Cập: Chữ tượng hình, viết trên giấy pa-pi-rút; giỏi hình học, hệ đếm thập phân; kim tự tháp, ướp xác."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 8. Ấn Độ cổ đại","req":["Nêu được điều kiện tự nhiên lưu vực sông Ấn, sông Hằng; chế độ xã hội (chế độ đẳng cấp); thành tựu văn hoá."],"sum":["Ấn Độ cổ đại nằm ở Nam Á, có hai con sông lớn là sông Ấn và sông Hằng bồi đắp đồng bằng màu mỡ.","Khái niệm: Ấn Độ cổ đại nằm ở Nam Á, có hai con sông lớn là sông Ấn và sông Hằng bồi đắp đồng bằng màu mỡ.","Từ khoá cần ghi nhớ: Sông Ấn; sông Hằng;","Mốc sự kiện cần nhớ: Khoảng 2500 TCN: người Đra-vi-đa xây thành thị ven sông Ấn; khoảng 1500 TCN: người A-ri-a tràn vào","Chế độ đẳng cấp (vác-na) gồm bốn đẳng cấp: Bra-man (tăng lữ), Ksa-tri-a (quý tộc, chiến binh), Vai-si-a (nông dân, thương nhân, thợ thủ công), Su-đra (người lao động nghèo); quy định khắt khe.","Thành tựu: Đạo Bà La Môn, đạo Phật (ra đời thế kỉ VI TCN); chữ Phạn; sử thi Ma-ha-bha-ra-ta, Ra-ma-y-a-na; chữ số 0 và hệ đếm thập phân; chùa hang, tháp Phật…"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 9. Trung Quốc từ thời cổ đại đến thế kỉ VII","req":["Nêu được điều kiện tự nhiên lưu vực Hoàng Hà, Trường Giang; quá trình thống nhất và xác lập chế độ phong kiến dưới thời Tần Thuỷ Hoàng; thành tựu văn minh."],"sum":["Trung Quốc có hai con sông lớn là Hoàng Hà và Trường Giang, bồi đắp đồng bằng rộng lớn. Nhà nước ra đời sớm: Hạ, Thương, Chu.","Khái niệm: Trung Quốc có hai con sông lớn là Hoàng Hà và Trường Giang, bồi đắp đồng bằng rộng lớn.","Từ khoá cần ghi nhớ: Hoàng Hà;","Mốc sự kiện cần nhớ: Năm 221 TCN, nhà Tần thống nhất Trung Quốc","Năm 221 TCN, nhà Tần thống nhất Trung Quốc: Tần Thuỷ Hoàng xưng hoàng đế, thống nhất đơn vị đo lường, tiền tệ, chữ viết, xây Vạn Lý Trường Thành.","Các triều đại tiếp theo: Hán, Tam quốc, Tấn, Nam – Bắc triều, Tuỳ (đến năm 618)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 10. Hy Lạp và La Mã cổ đại","req":["Nêu được điều kiện tự nhiên ảnh hưởng đến sự phát triển của Hy Lạp, La Mã; tổ chức nhà nước thành bang, đế chế; thành tựu văn hoá."],"sum":["Hy Lạp và La Mã nằm ven Địa Trung Hải, đất canh tác ít nhưng có nhiều vịnh, cảng biển, thuận lợi phát triển thủ công nghiệp và thương nghiệp đường biển.","Khái niệm: Hy Lạp và La Mã nằm ven Địa Trung Hải, đất canh tác ít nhưng có nhiều vịnh, cảng biển, thuận lợi phát triển thủ công nghiệp và thương nghiệp đường…","Từ khoá cần ghi nhớ: Hy Lạp;","Mốc sự kiện cần nhớ: Năm 27 TCN, La Mã chuyển từ cộng hoà sang đế chế do hoàng đế đứng đầu","Hy Lạp tổ chức theo thành bang (A-ten, Xpác-ta): A-ten có nền dân chủ chủ nô với Đại hội nhân dân.","Thành tựu: Chữ cái La-tinh (hệ chữ a, b, c); lịch dương 365 ngày 1/4; các nhà khoa học Ta-lét, Pi-ta-go, Ơ-clít, Ác-si-mét; triết học (Xô-crát, Pla-tôn,…"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương 4. Đông Nam Á từ những thế kỉ tiếp giáp đầu Công nguyên đến thế kỉ X","l":[{"t":"Bài 11. Các quốc gia sơ kì ở Đông Nam Á","req":["Trình bày được sơ lược vị trí địa lí khu vực Đông Nam Á; sự xuất hiện các quốc gia sơ kì."],"sum":["Đông Nam Á nằm ở phía đông nam châu Á, gồm Đông Nam Á lục địa và Đông Nam Á hải đảo; khí hậu nhiệt đới gió mùa, nhiều sông lớn, thuận lợi trồng lúa nước.","Khái niệm: Đông Nam Á nằm ở phía đông nam châu Á, gồm Đông Nam Á lục địa và Đông Nam Á hải đảo; khí hậu nhiệt đới gió mùa, nhiều sông lớn, thuận lợi trồng lúa…","Từ khoá cần ghi nhớ: Đông Nam Á;","Mốc sự kiện cần nhớ: Từ đầu Công nguyên, nhờ dùng đồ sắt, các quốc gia sơ kì ra đời","Từ những thế kỉ tiếp giáp đầu…: Từ những thế kỉ tiếp giáp đầu Công nguyên, nhờ sử dụng đồ sắt, kinh tế phát triển, các quốc gia sơ kì ra đời: Văn Lang – Âu Lạc, Chăm-pa, Phù Nam…","Cư dân trồng lúa nước, làm nghề…: Cư dân trồng lúa nước, làm nghề thủ công, buôn bán đường biển; các thương cảng như Óc Eo (Phù Nam) phát triển."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 12. Sự hình thành và bước đầu phát triển của các vương quốc phong kiến ở Đông Nam Á (từ thế kỉ VII đến thế kỉ X)","req":["Trình bày được sự hình thành và phát triển ban đầu của các vương quốc phong kiến Đông Nam Á; hoạt động kinh tế, thương mại."],"sum":["Từ thế kỉ VII đến thế kỉ X, các vương quốc phong kiến hình thành và phát triển: Chân Lạp, Chăm-pa (lục địa);","Khái niệm: Từ thế kỉ VII đến thế kỉ X, các vương quốc phong kiến hình thành và phát triển: Chân Lạp, Chăm-pa (lục địa);","Từ khoá cần ghi nhớ: Vương quốc phong kiến;","Mốc sự kiện cần nhớ: Từ thế kỉ VII đến thế kỉ X hình thành các vương quốc phong kiến;","Sri Vi-giay-a (thế kỉ VII) là vương…: Sri Vi-giay-a (thế kỉ VII) là vương quốc hùng mạnh ở hải đảo, kiểm soát eo biển Ma-lắc-ca.","Kinh tế: Nông nghiệp lúa nước là chủ đạo; thương mại biển phát triển với các thương cảng như Óc Eo, Pa-lem-bang."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 13. Giao lưu văn hoá ở Đông Nam Á từ đầu Công nguyên đến thế kỉ X","req":["Phân tích được những tác động chính của quá trình giao lưu văn hoá Ấn Độ, Trung Quốc đến Đông Nam Á."],"sum":["Đông Nam Á tiếp thu văn hoá Ấn Độ: tôn giáo (Hin-đu giáo, Phật giáo), chữ viết (chữ Phạn, cải biên thành chữ viết riêng), văn học (sử thi Ra-ma-y-a-na), kiến trúc (đền tháp).","Đông Nam Á tiếp thu văn hoá Ấn Độ: Tôn giáo (Hin-đu giáo, Phật giáo), chữ viết (chữ Phạn, cải biên thành chữ viết riêng), văn học (sử thi Ra-ma-y-a-na), kiến trúc (đền tháp).","Từ khoá cần ghi nhớ: Giao lưu văn hoá;","Mốc sự kiện cần nhớ: Từ đầu Công nguyên đến thế kỉ X, Đông Nam Á tiếp thu có chọn lọc văn hoá Ấn Độ và Trung Quốc","Đông Nam Á tiếp thu văn hoá Trung Quốc: Nho giáo, chữ Hán, kĩ thuật, chủ yếu ở Việt Nam.","Cư dân Đông Nam Á tiếp thu…: Cư dân Đông Nam Á tiếp thu có chọn lọc, kết hợp với văn hoá bản địa tạo nên bản sắc riêng; ví dụ đền tháp Chăm, khu đền Bô-rô-bu-đua (In-đô-nê-xi-a)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương 5. Việt Nam từ khoảng thế kỉ VII trước Công nguyên đến đầu thế kỉ X","l":[{"t":"Bài 14. Nhà nước Văn Lang – Âu Lạc","req":["Nêu được khoảng thời gian thành lập, không gian, tổ chức nhà nước Văn Lang, Âu Lạc; đời sống vật chất, tinh thần của cư dân."],"sum":["Khoảng thế kỉ VII TCN, nhà nước Văn Lang ra đời ở vùng đồng bằng Bắc Bộ và Bắc Trung Bộ ngày nay, đứng đầu là Hùng Vương, kinh đô Phong Châu (Phú Thọ).","Khái niệm: Khoảng thế kỉ VII TCN, nhà nước Văn Lang ra đời ở vùng đồng bằng Bắc Bộ và Bắc Trung Bộ ngày nay, đứng đầu là Hùng Vương, kinh đô Phong Châu (Phú…","Từ khoá cần ghi nhớ: Văn Lang;","Mốc sự kiện cần nhớ: Thế kỉ VII TCN: nhà nước Văn Lang ra đời; năm 208 TCN: Thục Phán lập nước Âu Lạc","Năm 208 TCN, Thục Phán lập nước…: Năm 208 TCN, Thục Phán lập nước Âu Lạc, xưng An Dương Vương, đóng đô ở Phong Khê (Cổ Loa, Đông Anh, Hà Nội); xây thành Cổ Loa, chế nỏ Liên châu.","Đời sống vật chất: Trồng lúa nước, chăn nuôi, đúc đồng (trống đồng Đông Sơn), ở nhà sàn, ăn cơm nếp, cơm tẻ, rau, cá."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 15. Chính sách cai trị của các triều đại phong kiến phương Bắc và sự chuyển biến của xã hội Âu Lạc","req":["Nêu được chính sách cai trị của phong kiến phương Bắc; những chuyển biến về kinh tế, xã hội, văn hoá thời Bắc thuộc."],"sum":["Từ năm 179 TCN đến năm 938, nước ta bị các triều đại phong kiến phương Bắc đô hộ (thời Bắc thuộc).","Khái niệm: Từ năm 179 TCN đến năm 938, nước ta bị các triều đại phong kiến phương Bắc đô hộ (thời Bắc thuộc).","Từ khoá cần ghi nhớ: Bắc thuộc; quận, huyện; cống nạp;","Mốc sự kiện cần nhớ: Từ năm 179 TCN đến năm 938 là thời Bắc thuộc","Chính sách cai trị: Chia nước ta thành các quận, huyện, sáp nhập vào lãnh thổ Trung Quốc; bóc lột nặng nề bằng tô thuế, cống nạp sản vật quý; nắm độc quyền muối, sắt;","Chuyển biến: Công cụ sắt phổ biến, dùng trâu bò kéo cày, làm thuỷ lợi; xuất hiện nghề mới (làm giấy, thuỷ tinh); xã hội phân hoá, mâu thuẫn giữa nhân dân với…"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 16. Các cuộc khởi nghĩa tiêu biểu giành độc lập trước thế kỉ X","req":["Trình bày được nét chính của các cuộc khởi nghĩa tiêu biểu: Hai Bà Trưng, Bà Triệu, Lý Bí, Mai Thúc Loan, Phùng Hưng."],"sum":["Khởi nghĩa Hai Bà Trưng (năm 40): nổ ra ở Mê Linh, đánh đuổi Tô Định, Trưng Trắc lên ngôi vua; năm 43 bị Mã Viện đàn áp.","Khởi nghĩa Hai Bà Trưng (năm 40): Nổ ra ở Mê Linh, đánh đuổi Tô Định, Trưng Trắc lên ngôi vua; năm 43 bị Mã Viện đàn áp.","Từ khoá cần ghi nhớ: Hai Bà Trưng;","Mốc sự kiện cần nhớ: Năm 40: Hai Bà Trưng; năm 248: Bà Triệu; năm 542: Lý Bí; năm 713: Mai Thúc Loan","Khởi nghĩa Bà Triệu (năm 248): Nổ ra ở Cửu Chân (Thanh Hoá), chống quân Ngô.","Khởi nghĩa Lý Bí (năm 542): Giành thắng lợi, năm 544 Lý Bí lên ngôi hoàng đế (Lý Nam Đế), đặt tên nước là Vạn Xuân, đóng đô ở vùng cửa sông Tô Lịch."],"e":["Hay nhầm: Mai Thúc Loan, Phùng Hưng."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 17. Cuộc đấu tranh bảo tồn và phát triển văn hoá dân tộc của người Việt","req":["Giải thích được nguyên nhân người Việt giữ được văn hoá; nêu được những giá trị văn hoá được bảo tồn và tiếp thu."],"sum":["Dù bị đô hộ hơn nghìn năm, người Việt vẫn giữ được tiếng nói của tổ tiên; các phong tục: ăn trầu, nhuộm răng, xăm mình, búi tóc; tín ngưỡng thờ cúng tổ tiên, thờ các anh hùng; lễ hội.","Khái niệm: Dù bị đô hộ hơn nghìn năm, người Việt vẫn giữ được tiếng nói của tổ tiên; các phong tục: ăn trầu, nhuộm răng, xăm mình, búi tóc; tín ngưỡng thờ cúng…","Từ khoá cần ghi nhớ: Bảo tồn văn hoá; tiếng Việt; phong tục; làng xã; tiếp thu có chọn lọc;","Mốc sự kiện cần nhớ: Trong hơn nghìn năm Bắc thuộc, người Việt giữ tiếng nói, phong tục và làng xã","Làng xã là nơi lưu giữ, bảo…: Làng xã là nơi lưu giữ, bảo tồn văn hoá dân tộc; các thế hệ người Việt truyền dạy tiếng nói, phong tục qua truyện kể, ca dao.","Người Việt tiếp thu có chọn lọc văn hoá Trung Hoa: Chữ Hán (đọc theo cách người Việt), Nho giáo, Phật giáo, Đạo giáo, kĩ thuật làm giấy, thuỷ tinh… để làm phong phú văn hoá dân tộc."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 18. Bước ngoặt lịch sử đầu thế kỉ X","req":["Trình bày được cuộc vận động tự chủ của họ Khúc, họ Dương; chiến thắng Bạch Đằng năm 938 và ý nghĩa."],"sum":["Năm 905, Khúc Thừa Dụ nổi dậy giành quyền tự chủ; Khúc Hạo tiến hành cải cách.","Năm 905, Khúc Thừa Dụ nổi dậy giành quyền tự chủ: Khúc Hạo tiến hành cải cách.","Từ khoá cần ghi nhớ: Khúc Thừa Dụ;","Mốc sự kiện cần nhớ: Năm 905: Khúc Thừa Dụ giành quyền tự chủ; năm 931: Dương Đình Nghệ đánh quân Nam Hán; năm 938: Ngô Quyền thắng trên sông Bạch Đằng","Năm 937, Kiều Công Tiễn giết Dương…: Năm 937, Kiều Công Tiễn giết Dương Đình Nghệ, cầu cứu quân Nam Hán.","Năm 938, Ngô Quyền dùng kế đóng…: Năm 938, Ngô Quyền dùng kế đóng cọc gỗ đầu bịt sắt ở cửa sông Bạch Đằng, lợi dụng thuỷ triều, nhử địch vào bãi cọc khi nước lên, rồi phản công khi…"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 19. Vương quốc Chăm-pa từ thế kỉ II đến thế kỉ X","req":["Mô tả được sự thành lập, quá trình phát triển, tình hình kinh tế, văn hoá của Chăm-pa."],"sum":["Năm 192, Khu Liên lãnh đạo nhân dân huyện Tượng Lâm (thuộc quận Nhật Nam) nổi dậy, lập nước Lâm Ấp, sau đổi là Chăm-pa; lãnh thổ ở vùng Trung Bộ ngày nay.","Khái niệm: Năm 192, Khu Liên lãnh đạo nhân dân huyện Tượng Lâm (thuộc quận Nhật Nam) nổi dậy, lập nước Lâm Ấp, sau đổi là Chăm-pa; lãnh thổ ở vùng Trung Bộ…","Từ khoá cần ghi nhớ: Khu Liên;","Mốc sự kiện cần nhớ: Năm 192: Khu Liên lập nước Lâm Ấp, sau đổi là Chăm-pa","Kinh tế: Trồng lúa nước trên ruộng bậc thang, làm guồng nước; khai thác lâm sản (trầm hương, ngà voi);","Văn hoá: Chữ viết bắt nguồn từ chữ Phạn; theo Hin-đu giáo và Phật giáo; kiến trúc đền tháp (thánh địa Mỹ Sơn, tháp Pô Na-ga); tục hoả táng người chết."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 20. Vương quốc Phù Nam","req":["Mô tả được sự thành lập, phát triển, kinh tế, văn hoá của Phù Nam."],"sum":["Phù Nam được thành lập khoảng thế kỉ I, trên cơ sở văn hoá Óc Eo, thuộc vùng Nam Bộ Việt Nam ngày nay.","Khái niệm: Phù Nam được thành lập khoảng thế kỉ I, trên cơ sở văn hoá Óc Eo, thuộc vùng Nam Bộ Việt Nam ngày nay.","Từ khoá cần ghi nhớ: Phù Nam;","Mốc sự kiện cần nhớ: Thành lập khoảng thế kỉ I; phát triển mạnh thế kỉ III–V; thế kỉ VII bị Chân Lạp thôn tính","Kinh tế: Nông nghiệp lúa nước kết hợp thủ công (làm gốm, đồ trang sức) và đặc biệt là thương mại biển;","Văn hoá: Tiếp thu chữ viết, tôn giáo (Hin-đu giáo, Phật giáo) từ Ấn Độ; cư dân ở nhà sàn; nghệ thuật điêu khắc, kiến trúc phát triển."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]}]},{"t":"Bài tập nâng cao","c":[{"t":"Chương 1. Vì sao phải học lịch sử?","l":[{"t":"Bài tập nâng cao · Chương 1. Vì sao phải học lịch sử? (6 câu)","q":{"n":6,"lv":{"Nâng cao":6}}}]},{"t":"Chương 2. Thời kì nguyên thuỷ","l":[{"t":"Bài tập nâng cao · Chương 2. Thời kì nguyên thuỷ (6 câu)","q":{"n":6,"lv":{"Nâng cao":6}}}]},{"t":"Chương 3. Xã hội cổ đại","l":[{"t":"Bài tập nâng cao · Chương 3. Xã hội cổ đại (8 câu)","e":["Hay nhầm: Không phải nguyên nhân chính."],"q":{"n":8,"lv":{"Nâng cao":8}}}]},{"t":"Chương 4. Đông Nam Á từ những thế kỉ tiếp giáp đầu Công nguyên đến thế kỉ X","l":[{"t":"Bài tập nâng cao · Chương 4. Đông Nam Á từ những thế kỉ tiếp giáp đầu Công nguyên đến thế kỉ X (6 câu)","q":{"n":6,"lv":{"Nâng cao":6}}}]},{"t":"Chương 5. Việt Nam từ khoảng thế kỉ VII trước Công nguyên đến đầu thế kỉ X","l":[{"t":"Bài tập nâng cao · Chương 5. Việt Nam từ khoảng thế kỉ VII trước Công nguyên đến đầu thế kỉ X (14 câu)","e":["Hay nhầm: Không phải nguyên nhân chính."],"q":{"n":14,"lv":{"Nâng cao":14}}}]}]}]},{"id":"diali","name":"Địa lí","b":[{"t":"Địa lí 6","c":[{"t":"Chương 1. Bản đồ – phương tiện thể hiện bề mặt Trái Đất","l":[{"t":"Bài 1. Hệ thống kinh, vĩ tuyến. Toạ độ địa lí","req":["Xác định được kinh tuyến gốc, xích đạo, các bán cầu; ghi được toạ độ địa lí của một địa điểm."],"sum":["Kinh tuyến là những nửa đường tròn nối hai cực trên bề mặt quả Địa Cầu; vĩ tuyến là những vòng tròn bao quanh quả Địa Cầu, vuông góc với kinh tuyến.","Khái niệm: Kinh tuyến là những nửa đường tròn nối hai cực trên bề mặt quả Địa Cầu; vĩ tuyến là những vòng tròn bao quanh quả Địa Cầu, vuông góc với kinh tuyến.","Từ khoá cần ghi nhớ: Kinh tuyến; vĩ tuyến; kinh tuyến gốc; vĩ tuyến gốc;","Điểm nhấn ghi nhớ: Kinh tuyến gốc 0° đi qua đài Grin-uých (Anh);","Kinh tuyến gốc (0°) đi qua đài thiên văn Grin-uých (Anh): Vĩ tuyến gốc (0°) là Xích đạo, chia Trái Đất thành bán cầu Bắc và bán cầu Nam.","Kinh độ của một điểm là số…: Kinh độ của một điểm là số độ chỉ khoảng cách từ kinh tuyến đi qua điểm đó đến kinh tuyến gốc; vĩ độ là số độ chỉ khoảng cách từ vĩ tuyến đi qua…"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 2. Bản đồ. Một số lưới kinh, vĩ tuyến. Phương hướng trên bản đồ","req":["Nêu được khái niệm bản đồ; nhận biết một số lưới kinh, vĩ tuyến; xác định phương hướng trên bản đồ."],"sum":["Bản đồ là hình ảnh thu nhỏ một phần hay toàn bộ bề mặt Trái Đất lên mặt phẳng, dựa trên một phép chiếu nhất định và được thể hiện bằng các kí hiệu bản đồ.","Khái niệm: Bản đồ là hình ảnh thu nhỏ một phần hay toàn bộ bề mặt Trái Đất lên mặt phẳng, dựa trên một phép chiếu nhất định và được thể hiện bằng các kí hiệu…","Từ khoá cần ghi nhớ: Bản đồ; phép chiếu; lưới kinh, vĩ tuyến; phương hướng;","Điểm nhấn ghi nhớ: Trên bản đồ có lưới: trên là bắc, dưới là nam, phải là đông, trái là tây","Có nhiều lưới kinh, vĩ tuyến khác…: Có nhiều lưới kinh, vĩ tuyến khác nhau tuỳ theo phép chiếu; bản đồ càng ở xa trung tâm chiếu thì càng biến dạng.","Xác định phương hướng: Dựa vào mạng lưới kinh, vĩ tuyến – đầu trên kinh tuyến chỉ hướng bắc, đầu dưới chỉ hướng nam, bên phải vĩ tuyến là hướng đông, bên trái là hướng tây."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 3. Tỉ lệ bản đồ. Tính khoảng cách thực tế dựa vào tỉ lệ bản đồ","req":["Nêu được ý nghĩa của tỉ lệ bản đồ; tính được khoảng cách thực tế dựa vào tỉ lệ số và tỉ lệ thước."],"sum":["Tỉ lệ bản đồ cho biết mức độ thu nhỏ khoảng cách được vẽ trên bản đồ so với thực tế. Có hai dạng: tỉ lệ số (ví dụ 1 : 100 000) và tỉ lệ thước.","Khái niệm: Tỉ lệ bản đồ cho biết mức độ thu nhỏ khoảng cách được vẽ trên bản đồ so với thực tế.","Từ khoá cần ghi nhớ: Tỉ lệ số; tỉ lệ thước; tỉ lệ lớn, trung bình, nhỏ; khoảng cách thực tế.","Điểm nhấn ghi nhớ: 1 : 100 000 nghĩa là 1 cm trên bản đồ ứng với 1 km ngoài thực tế; mẫu số càng nhỏ, bản đồ càng chi tiết","Tỉ lệ 1: 100 000 nghĩa là 1 cm trên bản đồ ứng với 100 000 cm (1 km) ngoài thực tế.","Phân loại: Bản đồ tỉ lệ lớn (trên 1 : 200 000), trung bình (1 : 200 000 đến 1 : 1 000 000), nhỏ (dưới 1 : 1 000 000)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 4. Kí hiệu và bảng chú giải bản đồ. Tìm đường đi trên bản đồ","req":["Đọc được các kí hiệu bản đồ và chú giải; tìm được đường đi trên bản đồ."],"sum":["Kí hiệu bản đồ dùng để thể hiện vị trí, đặc điểm của các đối tượng địa lí. Ba loại kí hiệu: kí hiệu điểm (sân bay, nhà máy), kí hiệu đường (đường giao thông, ranh giới, sông), kí hiệu diện tích…","Khái niệm: Kí hiệu bản đồ dùng để thể hiện vị trí, đặc điểm của các đối tượng địa lí.","Từ khoá cần ghi nhớ: Kí hiệu điểm; kí hiệu đường; kí hiệu diện tích; bảng chú giải; hình học, chữ, tượng hình.","Điểm nhấn ghi nhớ: Ba loại kí hiệu: điểm – đường – diện tích;","Ba dạng kí hiệu: Hình học, chữ, tượng hình.","Tìm đường đi trên bản đồ: Xác định điểm xuất phát, điểm đến; chọn tuyến đường phù hợp (ngắn nhất, thuận tiện); dựa vào tỉ lệ để tính quãng đường."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 5. Lược đồ trí nhớ","req":["Nêu được khái niệm lược đồ trí nhớ; vẽ được lược đồ trí nhớ thể hiện đường đi."],"sum":["Lược đồ trí nhớ là thông tin không gian về thế giới được giữ lại trong trí óc con người. Mỗi người có lược đồ trí nhớ riêng về những nơi quen thuộc.","Khái niệm: Lược đồ trí nhớ là thông tin không gian về thế giới được giữ lại trong trí óc con người.","Từ khoá cần ghi nhớ: Lược đồ trí nhớ;","Điểm nhấn ghi nhớ: Vẽ lược đồ đường đi: điểm đầu, điểm cuối, đối tượng chính, hướng và khoảng cách ước lượng","Vẽ lược đồ trí nhớ đường đi: Xác định điểm xuất phát và điểm đến; vẽ các đối tượng chính trên đường (ngã ba, ngã tư, công trình, cây cối…); ghi hướng, khoảng cách ước lượng.","Lược đồ trí nhớ giúp định hướng…: Lược đồ trí nhớ giúp định hướng, tìm đường, mô tả một khu vực cho người khác."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương 2. Trái Đất – hành tinh của hệ Mặt Trời","l":[{"t":"Bài 6. Trái Đất trong hệ Mặt Trời","req":["Xác định được vị trí của Trái Đất trong hệ Mặt Trời; mô tả hình dạng, kích thước Trái Đất."],"sum":["Hệ Mặt Trời gồm Mặt Trời và 8 hành tinh quay quanh. Trái Đất là hành tinh thứ ba theo thứ tự xa dần Mặt Trời, khoảng cách trung bình khoảng 150 triệu km.","Hệ Mặt Trời gồm Mặt Trời và 8 hành tinh quay quanh: Trái Đất là hành tinh thứ ba theo thứ tự xa dần Mặt Trời, khoảng cách trung bình khoảng 150 triệu km.","Từ khoá cần ghi nhớ: Hệ Mặt Trời;","Điểm nhấn ghi nhớ: Trái Đất đứng thứ ba theo thứ tự xa dần Mặt Trời, cách khoảng 150 triệu km","Trái Đất có dạng hình cầu: Bán kính Xích đạo khoảng 6 378 km; chu vi Xích đạo khoảng 40 076 km; diện tích bề mặt khoảng 510 triệu km².","Nhờ dạng hình cầu, mọi nơi trên…: Nhờ dạng hình cầu, mọi nơi trên Trái Đất đều có ngày và đêm."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 7. Chuyển động tự quay quanh trục của Trái Đất và hệ quả","req":["Mô tả được chuyển động tự quay của Trái Đất; trình bày hệ quả: ngày đêm luân phiên, giờ trên Trái Đất, lệch hướng chuyển động."],"sum":["Trái Đất tự quay quanh một trục tưởng tượng nối hai cực, nghiêng 66°33′ trên mặt phẳng quỹ đạo, theo hướng từ tây sang đông, một vòng hết 24 giờ.","Khái niệm: Trái Đất tự quay quanh một trục tưởng tượng nối hai cực, nghiêng 66°33′ trên mặt phẳng quỹ đạo, theo hướng từ tây sang đông, một vòng hết 24 giờ.","Từ khoá cần ghi nhớ: Tự quay; trục nghiêng 66°33′; giờ; khu vực giờ; lệch hướng chuyển động; kinh tuyến 180°.","Điểm nhấn ghi nhớ: Một vòng 24 giờ;","Hệ quả: Ngày đêm luân phiên nhau khắp mọi nơi trên Trái Đất; giờ trên Trái Đất – bề mặt chia thành 24 khu vực giờ, mỗi khu vực rộng 15° kinh tuyến; khu vực…","Hệ quả khác: Các vật chuyển động trên bề mặt Trái Đất bị lệch hướng – ở bán cầu Bắc lệch về bên phải, bán cầu Nam lệch về bên trái (theo hướng chuyển động)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 8. Chuyển động của Trái Đất quanh Mặt Trời và hệ quả","req":["Mô tả được chuyển động của Trái Đất quanh Mặt Trời; trình bày hệ quả: các mùa, hiện tượng ngày đêm dài ngắn theo mùa."],"sum":["Trái Đất chuyển động quanh Mặt Trời theo quỹ đạo hình elip gần tròn, hướng từ tây sang đông; một vòng hết 365 ngày 6 giờ.","Khái niệm: Trái Đất chuyển động quanh Mặt Trời theo quỹ đạo hình elip gần tròn, hướng từ tây sang đông; một vòng hết 365 ngày 6 giờ.","Từ khoá cần ghi nhớ: Quỹ đạo elip; mùa; xuân phân; hạ chí; thu phân;","Điểm nhấn ghi nhớ: Một vòng 365 ngày 6 giờ;","Hệ quả: Sinh ra các mùa.","Hiện tượng ngày đêm dài ngắn theo mùa: Mùa hạ ngày dài đêm ngắn, mùa đông ngày ngắn đêm dài (bán cầu Bắc)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 9. Xác định phương hướng ngoài thực tế","req":["Xác định được phương hướng ngoài thực tế dựa vào Mặt Trời, sao, la bàn."],"sum":["Dựa vào Mặt Trời: buổi sáng Mặt Trời mọc ở phía đông, buổi chiều lặn ở phía tây. Đứng giang tay phải chỉ hướng Mặt Trời mọc thì trước mặt là hướng bắc, sau lưng là hướng nam.","Dựa vào Mặt Trời: Buổi sáng Mặt Trời mọc ở phía đông, buổi chiều lặn ở phía tây.","Từ khoá cần ghi nhớ: Mặt Trời mọc; sao Bắc Cực; chòm Thập Tự Phương Nam; la bàn.","Điểm nhấn ghi nhớ: Mặt Trời mọc ở đông, lặn ở tây; giang tay phải về phía Mặt Trời mọc thì trước mặt là bắc","Dựa vào sao: Ở bán cầu Bắc, sao Bắc Cực chỉ hướng bắc;","Dùng la bàn: Kim nam châm luôn chỉ hướng bắc – nam;"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương 3. Cấu tạo của Trái Đất. Vỏ Trái Đất","l":[{"t":"Bài 10. Cấu tạo của Trái Đất. Các mảng kiến tạo","req":["Trình bày được cấu tạo của Trái Đất gồm ba lớp; xác định các mảng kiến tạo lớn và các đới tiếp giáp."],"sum":["Trái Đất gồm ba lớp: vỏ Trái Đất (dày 5–70 km, rắn chắc, nhiệt độ tăng dần theo độ sâu), man-ti (dày khoảng 2 900 km, trạng thái quánh dẻo đến rắn), nhân (dày khoảng 3 400 km, nhân ngoài lỏng, nhân…","Trái Đất gồm ba lớp: Vỏ Trái Đất (dày 5–70 km, rắn chắc, nhiệt độ tăng dần theo độ sâu), man-ti (dày khoảng 2 900 km, trạng thái quánh dẻo đến rắn), nhân (dày khoảng 3…","Từ khoá cần ghi nhớ: Vỏ Trái Đất; man-ti; nhân; thạch quyển; mảng kiến tạo.","Điểm nhấn ghi nhớ: Ba lớp: vỏ (5–70 km), man-ti (khoảng 2 900 km), nhân (khoảng 3 400 km); các mảng dịch chuyển vài cm mỗi năm","Vỏ Trái Đất gồm vỏ lục địa và vỏ đại dương: Thạch quyển gồm vỏ Trái Đất và phần trên của man-ti, bị nứt vỡ thành các mảng kiến tạo.","Các mảng kiến tạo lớn: Âu – Á, Phi, Ấn Độ – Ô-xtrây-li-a, Bắc Mỹ, Nam Mỹ, Nam Cực, Thái Bình Dương."],"e":["Hay nhầm: Không thuộc cấu tạo trong."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 11. Quá trình nội sinh và quá trình ngoại sinh. Hiện tượng tạo núi","req":["Phân biệt quá trình nội sinh và ngoại sinh; trình bày tác động đồng thời của hai quá trình trong hiện tượng tạo núi."],"sum":["Quá trình nội sinh xảy ra trong lòng Trái Đất, do nguồn năng lượng bên trong; làm di chuyển các mảng kiến tạo, nén ép các lớp đất đá, gây uốn nếp, đứt gãy, động đất, núi lửa; tạo ra các dạng địa…","Khái niệm: Quá trình nội sinh xảy ra trong lòng Trái Đất, do nguồn năng lượng bên trong; làm di chuyển các mảng kiến tạo, nén ép các lớp đất đá, gây uốn nếp,…","Từ khoá cần ghi nhớ: Quá trình nội sinh; quá trình ngoại sinh; tạo núi; phong hoá; bóc mòn; bồi tụ.","Điểm nhấn ghi nhớ: Nội sinh nâng lên và tạo địa hình lớn; ngoại sinh san bằng và bào mòn","Quá trình ngoại sinh xảy ra trên…: Quá trình ngoại sinh xảy ra trên bề mặt Trái Đất, do năng lượng Mặt Trời, gió, nước chảy, sinh vật, con người; phá huỷ, san bằng địa hình (phong…","Hai quá trình xảy ra đồng thời…: Hai quá trình xảy ra đồng thời và có tác động trái ngược nhau."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 12. Núi lửa và động đất","req":["Trình bày được hiện tượng núi lửa, động đất; nguyên nhân, tác hại và cách ứng phó."],"sum":["Núi lửa là hiện tượng phun trào mac-ma lên bề mặt Trái Đất. Núi lửa gồm miệng, ống phun, lò mac-ma.","Núi lửa là hiện tượng phun trào mac-ma lên bề mặt Trái Đất: Núi lửa gồm miệng, ống phun, lò mac-ma.","Từ khoá cần ghi nhớ: Núi lửa; mac-ma;","Điểm nhấn ghi nhớ: Khi động đất ở trong nhà, chui xuống gầm bàn chắc chắn và tránh xa cửa kính","Động đất là hiện tượng các lớp…: Động đất là hiện tượng các lớp đất đá gần mặt đất bị rung chuyển.","Tác hại: Phá huỷ nhà cửa, công trình, gây sóng thần, thiệt hại về người."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 13. Các dạng địa hình chính trên Trái Đất. Khoáng sản","req":["Phân biệt các dạng địa hình chính: núi, đồi, cao nguyên, đồng bằng; nêu khái niệm khoáng sản, phân loại."],"sum":["Núi là dạng địa hình nhô cao rõ rệt, độ cao tuyệt đối trên 500 m; có đỉnh, sườn, chân. Đồi có độ cao tương đối dưới 200 m, đỉnh tròn, sườn thoải.","Khái niệm: Núi là dạng địa hình nhô cao rõ rệt, độ cao tuyệt đối trên 500 m; có đỉnh, sườn, chân.","Từ khoá cần ghi nhớ: Núi;","Điểm nhấn ghi nhớ: Núi và cao nguyên trên 500 m;","Cao nguyên có bề mặt tương đối…: Cao nguyên có bề mặt tương đối bằng phẳng hoặc gợn sóng, độ cao tuyệt đối trên 500 m, sườn dốc.","Độ cao tuyệt đối tính từ mực nước biển: Độ cao tương đối tính từ chân lên đỉnh."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương 4. Khí hậu và biến đổi khí hậu","l":[{"t":"Bài 15. Lớp vỏ khí của Trái Đất. Khí áp và gió","req":["Mô tả các tầng khí quyển, thành phần không khí; các khối khí; khí áp, các đai khí áp và gió chính."],"sum":["Khí quyển gồm các tầng: đối lưu (0–16 km, tập trung khoảng 90% không khí, nơi sinh ra các hiện tượng thời tiết), bình lưu (16–80 km, có lớp ô-dôn), các tầng cao.","Khí quyển gồm các tầng: Đối lưu (0–16 km, tập trung khoảng 90% không khí, nơi sinh ra các hiện tượng thời tiết), bình lưu (16–80 km, có lớp ô-dôn), các tầng cao.","Từ khoá cần ghi nhớ: Khí quyển; tầng đối lưu; tầng bình lưu; tầng ô-dôn; khí áp; gió.","Điểm nhấn ghi nhớ: Tầng đối lưu từ 0 đến 16 km chứa khoảng 90% không khí; khí áp chuẩn 760 mm thuỷ ngân","Các khối khí: Nóng (vĩ độ thấp), lạnh (vĩ độ cao), đại dương (ẩm), lục địa (khô).","Khí áp là sức ép của khí…: Khí áp là sức ép của khí quyển lên bề mặt Trái Đất, đo bằng khí áp kế; khí áp trung bình chuẩn 760 mm thuỷ ngân."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 16. Nhiệt độ không khí. Mây và mưa","req":["Trình bày được sự thay đổi nhiệt độ không khí theo vĩ độ, độ cao; mây và mưa; đo nhiệt độ, lượng mưa."],"sum":["Nhiệt độ không khí do mặt đất hấp thụ năng lượng Mặt Trời rồi bức xạ lại. Đo bằng nhiệt kế đặt trong lều khí tượng cách mặt đất 1,5 m.","Khái niệm: Nhiệt độ không khí do mặt đất hấp thụ năng lượng Mặt Trời rồi bức xạ lại.","Từ khoá cần ghi nhớ: Nhiệt độ;","Điểm nhấn ghi nhớ: Lên cao 100 m, nhiệt độ giảm khoảng 0,6 °C","Nhiệt độ thay đổi theo vĩ độ…: Nhiệt độ thay đổi theo vĩ độ (giảm dần từ Xích đạo về cực), theo độ cao (lên cao 100 m giảm 0,6 °C), theo vị trí gần hay xa biển.","Độ ẩm không khí: Không khí chứa hơi nước."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 17. Thời tiết và khí hậu. Biến đổi khí hậu","req":["Phân biệt thời tiết và khí hậu; trình bày các đới khí hậu; biểu hiện của biến đổi khí hậu và biện pháp ứng phó."],"sum":["Thời tiết là trạng thái của khí quyển tại một thời điểm và khu vực cụ thể, luôn thay đổi. Khí hậu là sự lặp đi lặp lại của tình hình thời tiết ở một nơi trong thời gian dài, mang tính quy luật.","Khái niệm: Thời tiết là trạng thái của khí quyển tại một thời điểm và khu vực cụ thể, luôn thay đổi.","Từ khoá cần ghi nhớ: Thời tiết; khí hậu;","Điểm nhấn ghi nhớ: Thời tiết thay đổi hằng ngày, khí hậu là quy luật lặp lại nhiều năm; có 5 đới khí hậu: 1 nóng, 2 ôn hoà, 2 lạnh","Trên Trái Đất có 5 đới khí hậu: 1 đới nóng (nằm giữa hai chí tuyến), 2 đới ôn hoà (từ chí tuyến đến vòng cực), 2 đới lạnh (từ vòng cực đến cực).","Biến đổi khí hậu là sự thay…: Biến đổi khí hậu là sự thay đổi của khí hậu so với trung bình nhiều năm, chủ yếu do hoạt động của con người làm tăng khí nhà kính."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương 5. Nước trên Trái Đất","l":[{"t":"Bài 19. Thuỷ quyển và vòng tuần hoàn lớn của nước","req":["Kể được tên các thành phần của thuỷ quyển; mô tả vòng tuần hoàn lớn của nước."],"sum":["Thuỷ quyển là toàn bộ lớp nước bao quanh Trái Đất, gồm nước ở biển và đại dương (khoảng 97,5%), nước ngọt (khoảng 2,5%: băng, nước ngầm, nước mặt), hơi nước trong khí quyển.","Khái niệm: Thuỷ quyển là toàn bộ lớp nước bao quanh Trái Đất, gồm nước ở biển và đại dương (khoảng 97,5%), nước ngọt (khoảng 2,5%: băng, nước ngầm, nước mặt),…","Từ khoá cần ghi nhớ: Thuỷ quyển; tuần hoàn lớn của nước; bốc hơi; ngưng tụ; nước ngầm; băng.","Điểm nhấn ghi nhớ: Nước mặn chiếm khoảng 97,5%, nước ngọt khoảng 2,5%; trong nước ngọt, băng chiếm khoảng 68,7%","Trong nước ngọt, băng chiếm khoảng 68,7%…: Trong nước ngọt, băng chiếm khoảng 68,7%, nước ngầm khoảng 30,1%, nước mặt và nước khác khoảng 1,2%.","Vòng tuần hoàn lớn của nước: Nước biển bốc hơi → hơi nước được gió đưa vào đất liền, ngưng tụ thành mây, gây mưa → nước mưa chảy thành dòng chảy mặt (sông, suối) và ngấm xuống…"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 20. Sông và hồ. Nước ngầm và băng hà","req":["Mô tả các bộ phận của dòng sông, lưu vực; mối quan hệ mùa lũ với nguồn cung cấp nước; vai trò của sông, hồ, nước ngầm, băng hà."],"sum":["Sông là dòng chảy tự nhiên, thường xuyên, tương đối ổn định trên bề mặt lục địa. Hệ thống sông gồm sông chính, phụ lưu (đổ nước vào sông chính), chi lưu (thoát nước cho sông chính).","Khái niệm: Sông là dòng chảy tự nhiên, thường xuyên, tương đối ổn định trên bề mặt lục địa.","Từ khoá cần ghi nhớ: Sông; lưu vực; phụ lưu; chi lưu; lưu lượng; chế độ nước; hồ; nước ngầm; băng hà.","Điểm nhấn ghi nhớ: Lưu lượng là lượng nước qua mặt cắt trong 1 giây, đơn vị m³/s","Lưu lượng là lượng nước chảy qua…: Lưu lượng là lượng nước chảy qua mặt cắt ngang lòng sông trong 1 giây (m³/s).","Hồ là vùng trũng chứa nước trên…: Hồ là vùng trũng chứa nước trên bề mặt lục địa (hồ tự nhiên, hồ nhân tạo)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 21. Biển và đại dương","req":["Xác định được các đại dương; nêu được độ muối, nhiệt độ nước biển; các vận động của nước biển: sóng, thuỷ triều, dòng biển."],"sum":["Có bốn đại dương: Thái Bình Dương (lớn nhất), Đại Tây Dương, Ấn Độ Dương, Bắc Băng Dương.","Có bốn đại dương: Thái Bình Dương (lớn nhất), Đại Tây Dương, Ấn Độ Dương, Bắc Băng Dương.","Từ khoá cần ghi nhớ: Đại dương;","Điểm nhấn ghi nhớ: Bốn đại dương, Thái Bình Dương lớn nhất;","Nước biển có độ muối trung bình…: Nước biển có độ muối trung bình khoảng 35‰; nhiệt độ bề mặt giảm dần từ Xích đạo về hai cực.","Sóng biển là sự dao động tại…: Sóng biển là sự dao động tại chỗ của nước biển, chủ yếu do gió; sóng thần do động đất, núi lửa dưới đáy biển."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương 6. Đất và sinh vật trên Trái Đất","l":[{"t":"Bài 22. Lớp đất trên Trái Đất","req":["Nêu được các tầng đất, thành phần chính của đất; các nhân tố hình thành đất; một số nhóm đất điển hình."],"sum":["Đất là lớp vật chất mỏng, vụn bở bao phủ trên bề mặt lục địa và đảo, có độ phì. Các tầng đất: tầng chứa mùn (tầng hữu cơ), tầng tích tụ, tầng đá mẹ.","Khái niệm: Đất là lớp vật chất mỏng, vụn bở bao phủ trên bề mặt lục địa và đảo, có độ phì.","Từ khoá cần ghi nhớ: Đất;","Điểm nhấn ghi nhớ: Thành phần đất: khoáng khoảng 45%, nước 25%, không khí 25%, chất hữu cơ 5%","Thành phần của đất: Thành phần khoáng (khoảng 45%), chất hữu cơ (khoảng 5%), nước (khoảng 25%), không khí (khoảng 25%).","Các nhân tố hình thành đất: Đá mẹ, khí hậu, sinh vật, địa hình, thời gian, con người."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 23. Sự sống trên Trái Đất","req":["Nêu được sự đa dạng của thế giới sinh vật ở lục địa, đại dương."],"sum":["Sinh vật trên Trái Đất rất đa dạng, phân bố ở khắp nơi: trên lục địa, trong biển và đại dương, trong không khí, trong đất.","Sinh vật trên Trái Đất rất đa dạng, phân bố ở khắp nơi: Trên lục địa, trong biển và đại dương, trong không khí, trong đất.","Từ khoá cần ghi nhớ: Đa dạng sinh vật; phân bố theo vĩ độ; phân bố theo độ cao; sinh vật biển.","Điểm nhấn ghi nhớ: Thực vật thay đổi theo vĩ độ và độ cao, sinh vật biển phân bố theo độ sâu","Ở lục địa: Thực vật thay đổi theo vĩ độ và độ cao (từ rừng mưa nhiệt đới, xa-van, rừng lá rộng, rừng lá kim đến đài nguyên);","Ở đại dương: Sinh vật phong phú, phân bố theo độ sâu; sinh vật phù du, rong, tảo ở tầng mặt; cá, mực, động vật đáy ở các tầng sâu."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 24. Rừng nhiệt đới","req":["Trình bày được đặc điểm của rừng nhiệt đới; sự cần thiết phải bảo vệ rừng nhiệt đới."],"sum":["Rừng nhiệt đới phân bố ở vùng nội chí tuyến (giữa hai chí tuyến), nơi có khí hậu nóng, ẩm, mưa nhiều.","Khái niệm: Rừng nhiệt đới phân bố ở vùng nội chí tuyến (giữa hai chí tuyến), nơi có khí hậu nóng, ẩm, mưa nhiều.","Từ khoá cần ghi nhớ: Rừng nhiệt đới; nội chí tuyến; nhiều tầng; rừng mưa nhiệt đới; rừng nhiệt đới gió mùa; suy giảm.","Điểm nhấn ghi nhớ: Rừng thường có 4–5 tầng; rừng mưa mưa quanh năm, rừng gió mùa có mùa khô","Đặc điểm: Rừng có nhiều tầng (thường 4–5 tầng), thực vật rất phong phú (cây gỗ lớn, dây leo, phong lan, tầm gửi);","Có hai kiểu chính: Rừng mưa nhiệt đới (mưa quanh năm, ví dụ A-ma-dôn) và rừng nhiệt đới gió mùa (có mùa khô, cây rụng lá vào mùa khô)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 25. Sự phân bố các đới thiên nhiên trên Trái Đất","req":["Xác định được các đới thiên nhiên trên Trái Đất và đặc điểm chính."],"sum":["Đới nóng: nằm giữa hai chí tuyến, nhiệt độ cao quanh năm, lượng mưa lớn; thực vật xanh tốt (rừng nhiệt đới, xa-van), động vật phong phú.","Đới nóng: Nằm giữa hai chí tuyến, nhiệt độ cao quanh năm, lượng mưa lớn; thực vật xanh tốt (rừng nhiệt đới, xa-van), động vật phong phú.","Từ khoá cần ghi nhớ: Đới nóng;","Điểm nhấn ghi nhớ: Đới nóng nằm giữa hai chí tuyến;","Đới ôn hoà: Nằm từ chí tuyến đến vòng cực ở hai bán cầu; khí hậu có bốn mùa rõ rệt; thảm thực vật thay đổi theo mùa (rừng lá rộng, rừng lá kim, thảo nguyên).","Đới lạnh: Từ vòng cực đến cực; khí hậu giá lạnh, băng tuyết phủ phần lớn thời gian; thực vật nghèo nàn (rêu, địa y), động vật có lớp mỡ dày, lông dày (gấu…"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương 7. Con người và thiên nhiên","l":[{"t":"Bài 27. Dân số và sự phân bố dân cư trên thế giới","req":["Đọc được biểu đồ quy mô dân số thế giới; trình bày và giải thích sự phân bố dân cư; nêu được một số thành phố đông dân."],"sum":["Dân số thế giới tăng nhanh, đặc biệt từ thế kỉ XIX; năm 2022 vượt 8 tỉ người.","Khái niệm: Dân số thế giới tăng nhanh, đặc biệt từ thế kỉ XIX; năm 2022 vượt 8 tỉ người.","Từ khoá cần ghi nhớ: Dân số; phân bố dân cư;","Điểm nhấn ghi nhớ: Dân số thế giới vượt 8 tỉ người năm 2022; dân cư tập trung ở đồng bằng và ven biển","Dân cư phân bố không đều: Tập trung đông ở đồng bằng, ven biển, nơi có khí hậu ấm áp, giao thông thuận lợi (Đông Á, Nam Á, Tây Âu); thưa thớt ở vùng núi cao, hoang mạc, vùng…","Một số thành phố đông dân nhất thế giới: Tô-ki-ô, Niu Đê-li, Thượng Hải, Xao Pao-lô, Mê-hi-cô Xi-ti…"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 28. Mối quan hệ giữa con người và thiên nhiên","req":["Nêu được các tác động của thiên nhiên lên hoạt động sản xuất, sinh hoạt của con người; tác động của con người làm thiên nhiên thay đổi."],"sum":["Thiên nhiên ảnh hưởng đến con người: là môi trường sống, cung cấp tài nguyên (đất, nước, khoáng sản, sinh vật);","Thiên nhiên ảnh hưởng đến con người: Là môi trường sống, cung cấp tài nguyên (đất, nước, khoáng sản, sinh vật);","Từ khoá cần ghi nhớ: Thiên nhiên; tài nguyên; thiên tai; tác động tích cực; tác động tiêu cực; hài hoà.","Điểm nhấn ghi nhớ: Thiên nhiên cung cấp tài nguyên, con người tác động theo cả hai chiều","Con người tác động đến thiên nhiên theo hai chiều: Tích cực (trồng rừng, cải tạo đất, xây hồ chứa, bảo tồn thiên nhiên) và tiêu cực (phá rừng, khai thác quá mức, gây ô nhiễm đất, nước, không khí).","Con người cần sống hài hoà với…: Con người cần sống hài hoà với thiên nhiên để phát triển bền vững."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 29. Bảo vệ tự nhiên và khai thác thông minh các tài nguyên thiên nhiên vì sự phát triển bền vững","req":["Nêu được ý nghĩa của việc bảo vệ tự nhiên và khai thác thông minh tài nguyên vì sự phát triển bền vững."],"sum":["Bảo vệ tự nhiên là bảo vệ môi trường sống của con người và sinh vật, giữ gìn đa dạng sinh học, giảm thiên tai.","Khái niệm: Bảo vệ tự nhiên là bảo vệ môi trường sống của con người và sinh vật, giữ gìn đa dạng sinh học, giảm thiên tai.","Từ khoá cần ghi nhớ: Bảo vệ tự nhiên; tài nguyên tái tạo; tài nguyên không tái tạo; phát triển bền vững;","Điểm nhấn ghi nhớ: Phát triển bền vững là đáp ứng nhu cầu hiện tại mà không làm tổn hại thế hệ tương lai","Khai thác thông minh tài nguyên: Tài nguyên tái tạo (đất, nước, sinh vật) cần khai thác đi đôi với phục hồi; tài nguyên không tái tạo (khoáng sản) cần khai thác tiết kiệm, tái chế,…","Phát triển bền vững là sự phát…: Phát triển bền vững là sự phát triển đáp ứng nhu cầu hiện tại mà không làm tổn hại đến khả năng đáp ứng nhu cầu của các thế hệ tương lai."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]}]},{"t":"Bài tập nâng cao","c":[{"t":"Chương 1. Bản đồ – phương tiện thể hiện bề mặt Trái Đất","l":[{"t":"Bài tập nâng cao · Chương 1. Bản đồ – phương tiện thể hiện bề mặt Trái Đất (10 câu)","q":{"n":10,"lv":{"Nâng cao":10}}}]},{"t":"Chương 2. Trái Đất – hành tinh của hệ Mặt Trời","l":[{"t":"Bài tập nâng cao · Chương 2. Trái Đất – hành tinh của hệ Mặt Trời (8 câu)","q":{"n":8,"lv":{"Nâng cao":8}}}]},{"t":"Chương 3. Cấu tạo của Trái Đất. Vỏ Trái Đất","l":[{"t":"Bài tập nâng cao · Chương 3. Cấu tạo của Trái Đất. Vỏ Trái Đất (8 câu)","q":{"n":8,"lv":{"Nâng cao":8}}}]},{"t":"Chương 4. Khí hậu và biến đổi khí hậu","l":[{"t":"Bài tập nâng cao · Chương 4. Khí hậu và biến đổi khí hậu (6 câu)","q":{"n":6,"lv":{"Nâng cao":6}}}]},{"t":"Chương 5. Nước trên Trái Đất","l":[{"t":"Bài tập nâng cao · Chương 5. Nước trên Trái Đất (6 câu)","q":{"n":6,"lv":{"Nâng cao":6}}}]},{"t":"Chương 6. Đất và sinh vật trên Trái Đất","l":[{"t":"Bài tập nâng cao · Chương 6. Đất và sinh vật trên Trái Đất (8 câu)","q":{"n":8,"lv":{"Nâng cao":8}}}]},{"t":"Chương 7. Con người và thiên nhiên","l":[{"t":"Bài tập nâng cao · Chương 7. Con người và thiên nhiên (6 câu)","q":{"n":6,"lv":{"Nâng cao":6}}}]}]}]}]};
